export const SKETCHUP_MAIN_RB = "# Inertia CAD Bridge for SketchUp.\n#\n# A loopback TCP server that Inertia connects to. Every request runs on\n# SketchUp's main thread from a UI timer, carries the per-session token from the\n# discovery file, and uses one JSON object per line. Reads never change the\n# model. Edits are re-validated against the preview's fingerprints, shown to\n# the designer in a native Yes/No dialog, and applied as one undoable operation.\n# There is deliberately no way to run arbitrary Ruby through this bridge.\nrequire 'socket'\nrequire 'json'\nrequire 'securerandom'\nrequire 'fileutils'\nrequire 'digest'\nrequire 'base64'\nrequire 'tmpdir'\n\nmodule Inertia\n  module CadBridge\n    BRIDGE_VERSION = '1.1.0'.freeze\n    PROTOCOL = 1\n    MAX_REQUEST_BYTES = 1024 * 1024\n    MM_PER_INCH = 25.4\n    DEFAULT_LIMIT = 100\n    MAX_LIMIT = 500\n    MAX_VISITS = 50_000\n    MAX_OPERATIONS = 50\n    MAX_TARGETS = 500\n    MAX_COORDINATE_MM = 1.0e7\n    MAX_INFO_ITEMS = 500\n    MAX_CLIENTS = 8\n    IDLE_SECONDS = 10\n    LENGTH_UNITS = { 0 => 'in', 1 => 'ft', 2 => 'mm', 3 => 'cm', 4 => 'm', 5 => 'yd' }.freeze\n    QUERY_TYPES = %w[group component face edge text dimension image guide section_plane].freeze\n    AUTOCAD_ONLY_FILTERS = %w[layer layout textContains].freeze\n\n    class BridgeError < StandardError\n      attr_reader :code\n\n      def initialize(code, message)\n        super(message)\n        @code = code\n      end\n    end\n\n    @models = {}\n    @revisions = {}\n\n    class << self\n      attr_reader :port, :token\n    end\n\n    def self.fail!(code, message)\n      raise BridgeError.new(code, message)\n    end\n\n    # --- Documents -------------------------------------------------------\n\n    def self.model_alive?(model)\n      return false if model.nil?\n      model.respond_to?(:valid?) ? model.valid? : true\n    rescue StandardError\n      false\n    end\n\n    def self.open_models\n      list = []\n      # SketchUp 2027 can hold several models in one process. Use its list when\n      # this build has one; otherwise the active model is the only one we see.\n      if Sketchup.respond_to?(:models)\n        begin\n          Sketchup.models.each { |model| list << model }\n        rescue StandardError\n          list = []\n        end\n      end\n      active = Sketchup.active_model\n      list << active if active && list.none? { |model| model == active }\n      list.select { |model| model_alive?(model) }\n    end\n\n    def self.model_id(model)\n      @models.each { |id, known| return id if known == model }\n      id = \"skp:#{Process.pid}:#{SecureRandom.hex(4)}\"\n      @models[id] = model\n      @revisions[id] = 0\n      begin\n        model.add_observer(RevisionObserver.new(id))\n      rescue StandardError\n        nil\n      end\n      id\n    end\n\n    def self.bump(id)\n      @revisions[id] = (@revisions[id] || 0) + 1\n    end\n\n    def self.revision(id)\n      @revisions[id] || 0\n    end\n\n    def self.display_units(model)\n      LENGTH_UNITS[model.options['UnitsOptions']['LengthUnit']] || 'in'\n    rescue StandardError\n      'in'\n    end\n\n    def self.describe_model(model, active)\n      id = model_id(model)\n      title = model.title.to_s\n      path = model.path.to_s\n      {\n        'documentId' => id,\n        'app' => 'sketchup',\n        'name' => title.empty? ? 'Untitled' : title,\n        'path' => path.empty? ? nil : path,\n        'modified' => model.respond_to?(:modified?) ? model.modified? : nil,\n        'active' => model == active,\n        'revision' => revision(id),\n        'displayUnits' => display_units(model)\n      }\n    end\n\n    def self.documents(_params)\n      active = Sketchup.active_model\n      { 'documents' => open_models.map { |model| describe_model(model, active) } }\n    end\n\n    def self.model_for(document_id, require_active = false)\n      model = @models[document_id.to_s]\n      unless model_alive?(model)\n        fail!('DOCUMENT_NOT_FOUND', 'That SketchUp model is no longer open. Call inertia_cad_status for current documents.')\n      end\n      if require_active && model != Sketchup.active_model\n        fail!('INACTIVE_DOCUMENT', 'Bring this model to the front in SketchUp, then try again.')\n      end\n      model\n    end\n\n    # --- Entities --------------------------------------------------------\n\n    def self.type_name(entity)\n      case entity\n      when Sketchup::ComponentInstance then 'component'\n      when Sketchup::Group then 'group'\n      when Sketchup::Face then 'face'\n      when Sketchup::Edge then 'edge'\n      when Sketchup::Text then 'text'\n      when Sketchup::Dimension then 'dimension'\n      when Sketchup::Image then 'image'\n      when Sketchup::ConstructionLine, Sketchup::ConstructionPoint then 'guide'\n      when Sketchup::SectionPlane then 'section_plane'\n      else entity.class.name.to_s.split('::').last.to_s.downcase\n      end\n    end\n\n    def self.container?(entity)\n      entity.is_a?(Sketchup::Group) || entity.is_a?(Sketchup::ComponentInstance)\n    end\n\n    def self.tag_label(layer)\n      return nil if layer.nil?\n      layer.respond_to?(:display_name) ? layer.display_name : layer.name\n    end\n\n    def self.find_tag(model, name)\n      model.layers.find { |layer| layer.name == name || tag_label(layer) == name }\n    end\n\n    def self.find_material(model, name)\n      model.materials.find do |material|\n        material.name == name || (material.respond_to?(:display_name) && material.display_name == name)\n      end\n    end\n\n    def self.material_label(material)\n      return nil if material.nil?\n      material.respond_to?(:display_name) ? material.display_name : material.name\n    end\n\n    # True when the entity appears exactly once in the model, so an edit to it\n    # cannot leak into other copies of a component or copied group.\n    def self.unshared?(entity)\n      parent = entity.parent\n      guard = 0\n      while parent.is_a?(Sketchup::ComponentDefinition)\n        return false if parent.instances.size != 1 || guard > 64\n        instance = parent.instances.first\n        parent = instance.parent\n        guard += 1\n      end\n      true\n    end\n\n    def self.locked_chain?(entity)\n      return true if entity.respond_to?(:locked?) && entity.locked?\n      parent = entity.parent\n      guard = 0\n      while parent.is_a?(Sketchup::ComponentDefinition) && guard <= 64\n        instance = parent.instances.first\n        break if instance.nil?\n        return true if instance.respond_to?(:locked?) && instance.locked?\n        parent = instance.parent\n        guard += 1\n      end\n      false\n    end\n\n    # World transformation of the entity's parent context, along its first\n    # occurrence. Exact whenever the entity is unshared.\n    def self.parent_transform(entity)\n      transform = Geom::Transformation.new\n      parent = entity.parent\n      guard = 0\n      while parent.is_a?(Sketchup::ComponentDefinition) && guard <= 64\n        instance = parent.instances.first\n        break if instance.nil?\n        transform = instance.transformation * transform\n        parent = instance.parent\n        guard += 1\n      end\n      transform\n    end\n\n    def self.mm(value)\n      (value.to_f * MM_PER_INCH).round(2)\n    end\n\n    def self.bounds_mm(bounds, transform)\n      return nil if bounds.nil? || bounds.empty?\n      points = (0..7).map { |index| bounds.corner(index).transform(transform) }\n      {\n        'min' => [mm(points.map(&:x).min), mm(points.map(&:y).min), mm(points.map(&:z).min)],\n        'max' => [mm(points.map(&:x).max), mm(points.map(&:y).max), mm(points.map(&:z).max)]\n      }\n    end\n\n    def self.summarize(entity, transform, depth = nil, compact = false)\n      row = { 'id' => entity.persistent_id.to_s, 'type' => type_name(entity) }\n      if compact\n        row['tag'] = tag_label(entity.layer) if entity.respond_to?(:layer)\n        bounds = bounds_mm(entity.bounds, transform)\n        row['boundsMm'] = bounds if bounds\n        return row\n      end\n      if container?(entity)\n        row['name'] = entity.name.to_s\n        row['definition'] = entity.definition.name.to_s\n        row['children'] = entity.definition.entities.size\n      end\n      row['tag'] = tag_label(entity.layer) if entity.respond_to?(:layer)\n      material = entity.respond_to?(:material) ? entity.material : nil\n      row['material'] = material_label(material) if material\n      row['text'] = entity.text.to_s[0, 500] if entity.is_a?(Sketchup::Text)\n      # Measured in world space, like boundsMm, so scaled groups report true sizes.\n      row['areaMm2'] = (entity.area(transform) * MM_PER_INCH * MM_PER_INCH).round(1) if entity.is_a?(Sketchup::Face)\n      if entity.is_a?(Sketchup::Edge)\n        row['lengthMm'] = mm(entity.start.position.transform(transform).distance(entity.end.position.transform(transform)))\n      end\n      row['hidden'] = true if entity.respond_to?(:hidden?) && entity.hidden?\n      row['locked'] = true if entity.respond_to?(:locked?) && entity.locked?\n      row['shared'] = true unless unshared?(entity)\n      row['depth'] = depth unless depth.nil?\n      bounds = bounds_mm(entity.bounds, transform)\n      row['boundsMm'] = bounds if bounds\n      row\n    end\n\n    def self.limit_param(params)\n      value = params['limit'].to_i\n      value = DEFAULT_LIMIT if value <= 0\n      [value, MAX_LIMIT].min\n    end\n\n    def self.selection(params)\n      model = model_for(params['documentId'])\n      id = model_id(model)\n      limit = limit_param(params)\n      selected = model.selection.to_a\n      transform = model.respond_to?(:edit_transform) ? model.edit_transform : Geom::Transformation.new\n      active_path = model.active_path || []\n      {\n        'documentId' => id,\n        'revision' => revision(id),\n        'units' => 'mm',\n        'total' => selected.size,\n        'truncated' => selected.size > limit,\n        'editingInside' => active_path.map { |instance| instance.persistent_id.to_s },\n        'items' => selected.first(limit).map { |entity| summarize(entity, transform) }\n      }\n    end\n\n    def self.walk(entities, transform, depth, max_depth, state, &visit)\n      entities.each do |entity|\n        if state[:visits] >= MAX_VISITS\n          state[:capped] = true\n          return\n        end\n        state[:visits] += 1\n        visit.call(entity, transform, depth)\n        next unless depth < max_depth && container?(entity)\n        walk(entity.definition.entities, transform * entity.transformation, depth + 1, max_depth, state, &visit)\n        return if state[:capped]\n      end\n    end\n\n    # A plan-view rectangle in millimetres: crossing keeps anything that touches it, window only\n    # what lies fully inside.\n    def self.within_param(value)\n      return nil if value.nil?\n      message = 'within needs min and max as [x, y] in millimetres, with min below max.'\n      fail!('INVALID_REQUEST', message) unless value.is_a?(Hash)\n      corners = [value['min'], value['max']]\n      unless corners.all? { |corner| corner.is_a?(Array) && corner.size == 2 && corner.all? { |v| v.is_a?(Numeric) && v.to_f.finite? } }\n        fail!('INVALID_REQUEST', message)\n      end\n      min, max = corners.map { |corner| corner.map(&:to_f) }\n      fail!('INVALID_REQUEST', message) if min[0] > max[0] || min[1] > max[1]\n      mode = (value['mode'] || 'crossing').to_s\n      fail!('INVALID_REQUEST', 'within.mode must be crossing or window.') unless %w[crossing window].include?(mode)\n      { min: min, max: max, window: mode == 'window' }\n    end\n\n    def self.in_area?(bounds, area)\n      return false if bounds.nil?\n      low = bounds['min']\n      high = bounds['max']\n      if area[:window]\n        low[0] >= area[:min][0] && low[1] >= area[:min][1] && high[0] <= area[:max][0] && high[1] <= area[:max][1]\n      else\n        high[0] >= area[:min][0] && low[0] <= area[:max][0] && high[1] >= area[:min][1] && low[1] <= area[:max][1]\n      end\n    end\n\n    def self.query(params)\n      model = model_for(params['documentId'])\n      id = model_id(model)\n      foreign = AUTOCAD_ONLY_FILTERS.reject { |key| params[key].nil? }\n      unless foreign.empty?\n        fail!('INVALID_REQUEST', \"#{foreign.join(', ')} only work in AutoCAD. In SketchUp, filter by tag, nameContains, or types.\")\n      end\n      fields = (params['fields'] || 'full').to_s\n      fail!('INVALID_REQUEST', 'fields must be full or compact.') unless %w[full compact].include?(fields)\n      area = within_param(params['within'])\n      types = Array(params['types']).map(&:to_s)\n      types = %w[group component] if types.empty?\n      unknown = types - QUERY_TYPES\n      fail!('INVALID_REQUEST', \"Unknown types: #{unknown.join(', ')}. Use #{QUERY_TYPES.join(', ')}.\") unless unknown.empty?\n      tag = params['tag'] && params['tag'].to_s\n      needle = params['nameContains'] && params['nameContains'].to_s.downcase\n      max_depth = params['maxDepth'].nil? ? 8 : [[params['maxDepth'].to_i, 0].max, 32].min\n      offset = [params['cursor'].to_i, 0].max\n      limit = limit_param(params)\n      counts = Hash.new(0)\n      matches = []\n      state = { visits: 0, capped: false }\n      walk(model.entities, Geom::Transformation.new, 0, max_depth, state) do |entity, transform, depth|\n        kind = type_name(entity)\n        counts[kind] += 1\n        next unless types.include?(kind)\n        next if tag && tag_label(entity.respond_to?(:layer) ? entity.layer : nil) != tag\n        if needle\n          names = [entity.respond_to?(:name) ? entity.name.to_s : '']\n          names << entity.definition.name.to_s if container?(entity)\n          next unless names.any? { |name| name.downcase.include?(needle) }\n        end\n        next if area && !in_area?(bounds_mm(entity.bounds, transform), area)\n        matches << [entity, transform, depth]\n      end\n      page = matches[offset, limit] || []\n      result = {\n        'documentId' => id,\n        'revision' => revision(id),\n        'units' => 'mm',\n        'total' => matches.size,\n        'counts' => counts,\n        'items' => page.map { |entity, transform, depth| summarize(entity, transform, depth, fields == 'compact') }\n      }\n      result['nextCursor'] = (offset + limit).to_s if offset + limit < matches.size\n      result['scanCapped'] = true if state[:capped]\n      result\n    end\n\n    def self.capped(result, key, items)\n      result[key] = items.first(MAX_INFO_ITEMS)\n      result[\"#{key}Truncated\"] = true if items.size > MAX_INFO_ITEMS\n    end\n\n    def self.info(params)\n      model = model_for(params['documentId'])\n      id = model_id(model)\n      result = {\n        'documentId' => id,\n        'revision' => revision(id),\n        'units' => 'mm',\n        'displayUnits' => display_units(model),\n        'boundsMm' => bounds_mm(model.bounds, Geom::Transformation.new),\n        'entityCount' => model.entities.size\n      }\n      capped(result, 'tags', model.layers.map { |layer| { 'name' => tag_label(layer), 'visible' => layer.visible? } })\n      capped(result, 'materials', model.materials.map { |material| material_label(material) })\n      capped(result, 'scenes', model.pages.map { |page| page.name.to_s })\n      definitions = model.definitions.reject { |definition| definition.group? || definition.image? }\n      capped(result, 'componentDefinitions',\n             definitions.map { |definition| { 'name' => definition.name.to_s, 'instances' => definition.instances.size } })\n      result\n    end\n\n    def self.capture(params)\n      model = model_for(params['documentId'], true)\n      id = model_id(model)\n      view = model.active_view\n      max_width = [[params['maxWidth'].to_i, 64].max, 2048].min\n      max_height = [[params['maxHeight'].to_i, 64].max, 2048].min\n      scale = [max_width.to_f / view.vpwidth, max_height.to_f / view.vpheight, 1.0].min\n      width = [(view.vpwidth * scale).round, 1].max\n      height = [(view.vpheight * scale).round, 1].max\n      path = File.join(Dir.tmpdir, \"inertia-cad-#{SecureRandom.hex(6)}.png\")\n      begin\n        written = view.write_image(filename: path, width: width, height: height, antialias: true, transparent: false)\n        fail!('CAPTURE_FAILED', 'SketchUp could not export the view.') unless written && File.exist?(path)\n        data = Base64.strict_encode64(File.binread(path))\n      ensure\n        File.delete(path) if File.exist?(path)\n      end\n      page = model.pages.respond_to?(:selected_page) ? model.pages.selected_page : nil\n      {\n        'documentId' => id,\n        'revision' => revision(id),\n        'width' => width,\n        'height' => height,\n        'pngBase64' => data,\n        'scene' => page ? page.name : nil\n      }\n    end\n\n    # --- Edits -----------------------------------------------------------\n\n    def self.entity_for(model, raw_id)\n      pid = Integer(raw_id.to_s, 10)\n      entity = model.find_entity_by_persistent_id(pid)\n      unless entity && entity.valid?\n        fail!('TARGET_NOT_FOUND', \"Nothing with id #{raw_id} is in this model any more. Read the selection again.\")\n      end\n      entity\n    rescue ArgumentError\n      fail!('INVALID_REQUEST', \"#{raw_id.inspect} is not a SketchUp entity id.\")\n    end\n\n    def self.label(entity)\n      name = container?(entity) ? entity.name.to_s : ''\n      name = entity.definition.name.to_s if name.empty? && container?(entity)\n      name.empty? ? \"#{type_name(entity)} #{entity.persistent_id}\" : \"#{type_name(entity)} \\\"#{name}\\\" (#{entity.persistent_id})\"\n    end\n\n    def self.writable!(entity)\n      fail!('UNSUPPORTED_TARGET', \"#{label(entity)} cannot be edited through Inertia.\") unless entity.is_a?(Sketchup::Drawingelement)\n      unless unshared?(entity)\n        fail!('SHARED_DEFINITION',\n              \"#{label(entity)} sits inside a component or group that appears more than once, so this edit \" \\\n              'would change every copy. Pick a top-level object, or make that component unique in SketchUp first.')\n      end\n      fail!('LOCKED', \"#{label(entity)} is locked (or inside a locked group). Unlock it in SketchUp first.\") if locked_chain?(entity)\n    end\n\n    def self.fingerprint(entity)\n      parts = [type_name(entity), entity.persistent_id]\n      parts << entity.name.to_s << entity.definition.name.to_s << entity.transformation.to_a.map { |v| v.round(6) } if container?(entity)\n      parts << entity.layer.name if entity.respond_to?(:layer)\n      material = entity.respond_to?(:material) ? entity.material : nil\n      parts << (material ? material.name : '')\n      parts << (entity.respond_to?(:hidden?) && entity.hidden?)\n      bounds = entity.bounds\n      parts << [bounds.min.to_a, bounds.max.to_a].flatten.map { |v| v.to_f.round(6) } unless bounds.empty?\n      parts << contents_digest(entity.definition) if container?(entity)\n      Digest::SHA256.hexdigest(parts.join('|'))[0, 16]\n    end\n\n    # A container's direct contents, so an edit inside a group after the preview\n    # makes the preview stale. Capped so huge definitions stay cheap.\n    def self.contents_digest(definition)\n      entities = definition.entities\n      rows = entities.first(2000).map do |child|\n        child_bounds = child.bounds\n        material = child.respond_to?(:material) ? child.material : nil\n        [\n          child.persistent_id, type_name(child),\n          child.respond_to?(:layer) ? child.layer.name : '', material ? material.name : '',\n          child_bounds.empty? ? '' : [child_bounds.min.to_a, child_bounds.max.to_a].flatten.map { |v| v.to_f.round(6) }\n        ].join(',')\n      end\n      \"#{entities.size}:#{Digest::SHA256.hexdigest(rows.join(';'))[0, 16]}\"\n    end\n\n    def self.vector_param(value, name)\n      unless value.is_a?(Array) && value.size == 3 && value.all? { |v| v.is_a?(Numeric) && v.to_f.finite? && v.abs <= MAX_COORDINATE_MM }\n        fail!('INVALID_REQUEST', \"#{name} must be [x, y, z] in millimetres.\")\n      end\n      value.map(&:to_f)\n    end\n\n    def self.ids_param(op)\n      ids = Array(op['ids'])\n      ids = [op['id']] if ids.empty? && op['id']\n      fail!('INVALID_REQUEST', \"#{op['op']} needs at least one id.\") if ids.empty?\n      fail!('INVALID_REQUEST', \"#{op['op']} accepts at most #{MAX_TARGETS} ids.\") if ids.size > MAX_TARGETS\n      ids\n    end\n\n    def self.name_param(value, what)\n      name = value.to_s.strip\n      fail!('INVALID_REQUEST', \"#{what} needs a name.\") if name.empty? || name.size > 200\n      name\n    end\n\n    # Resolves and checks every operation without touching the model. Returns\n    # what the designer will see, fingerprints of everything the edit depends\n    # on, and the steps that perform it.\n    def self.plan(model, operations)\n      operations = Array(operations)\n      fail!('INVALID_REQUEST', 'Give at least one operation.') if operations.empty?\n      fail!('INVALID_REQUEST', \"At most #{MAX_OPERATIONS} operations per change.\") if operations.size > MAX_OPERATIONS\n      changes = []\n      fingerprints = {}\n      steps = []\n      new_tags = {}\n      new_materials = {}\n      warnings = []\n      # Tags as earlier operations in this batch leave them, so a later one is never skipped as a no-op.\n      projected_tags = {}\n      target = lambda do |raw_id|\n        entity = entity_for(model, raw_id)\n        writable!(entity)\n        fingerprints[\"entity:#{entity.persistent_id}\"] = fingerprint(entity)\n        entity\n      end\n      operations.each do |op|\n        kind = op['op'].to_s\n        case kind\n        when 'skp.create_tag'\n          name = name_param(op['name'], kind)\n          fail!('ALREADY_EXISTS', \"Tag \\\"#{name}\\\" already exists.\") if find_tag(model, name) || new_tags[name]\n          new_tags[name] = true\n          fingerprints[\"tag:#{name}\"] = 'absent'\n          changes << { 'op' => kind, 'target' => name, 'field' => 'tag', 'before' => nil, 'after' => 'created' }\n          steps << ->(_created) { model.layers.add(name) }\n        when 'skp.create_material'\n          name = name_param(op['name'], kind)\n          color = op['color'].to_s\n          fail!('INVALID_REQUEST', 'color must look like #RRGGBB.') unless color =~ /\\A#\\h{6}\\z/\n          alpha = op['alpha'].nil? ? nil : op['alpha'].to_f\n          fail!('INVALID_REQUEST', 'alpha must be between 0 and 1.') if alpha && !(alpha >= 0 && alpha <= 1)\n          fail!('ALREADY_EXISTS', \"Material \\\"#{name}\\\" already exists.\") if find_material(model, name) || new_materials[name]\n          new_materials[name] = true\n          fingerprints[\"material:#{name}\"] = 'absent'\n          changes << { 'op' => kind, 'target' => name, 'field' => 'material', 'before' => nil, 'after' => color }\n          steps << lambda do |_created|\n            material = model.materials.add(name)\n            material.color = Sketchup::Color.new(color[1, 2].hex, color[3, 2].hex, color[5, 2].hex)\n            material.alpha = alpha if alpha\n          end\n        when 'skp.set_tag'\n          name = name_param(op['tag'], kind)\n          fail!('TAG_NOT_FOUND', \"No tag named \\\"#{name}\\\". Create it first with skp.create_tag.\") unless find_tag(model, name) || new_tags[name]\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            existing = find_tag(model, name)\n            after = existing ? tag_label(existing) : name\n            before = projected_tags.fetch(entity.persistent_id) { tag_label(entity.layer) }\n            if before == after\n              warnings << \"#{label(entity)} already has tag #{after}.\"\n              next\n            end\n            projected_tags[entity.persistent_id] = after\n            changes << { 'op' => kind, 'target' => label(entity), 'field' => 'tag', 'before' => before, 'after' => after }\n            steps << ->(_created) { entity.layer = find_tag(model, name) }\n          end\n        when 'skp.set_material'\n          name = name_param(op['material'], kind)\n          unless find_material(model, name) || new_materials[name]\n            fail!('MATERIAL_NOT_FOUND', \"No material named \\\"#{name}\\\" in this model. Create it with skp.create_material.\")\n          end\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            before = material_label(entity.material)\n            changes << { 'op' => kind, 'target' => label(entity), 'field' => 'material', 'before' => before, 'after' => name }\n            steps << ->(_created) { entity.material = find_material(model, name) }\n          end\n        when 'skp.rename'\n          name = op['name'].to_s.strip\n          fail!('INVALID_REQUEST', 'name must be at most 200 characters.') if name.size > 200\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            fail!('UNSUPPORTED_TARGET', \"Only groups and components have names; #{label(entity)} does not.\") unless container?(entity)\n            changes << { 'op' => kind, 'target' => label(entity), 'field' => 'name', 'before' => entity.name.to_s, 'after' => name }\n            steps << ->(_created) { entity.name = name }\n          end\n        when 'skp.move'\n          vector_mm = vector_param(op['vectorMm'], 'vectorMm')\n          world = Geom::Vector3d.new(*vector_mm.map { |v| v / MM_PER_INCH })\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            fail!('UNSUPPORTED_TARGET', \"Only groups and components can be moved; #{label(entity)} cannot.\") unless container?(entity)\n            local = world.transform(parent_transform(entity).inverse)\n            changes << { 'op' => kind, 'target' => label(entity), 'field' => 'position', 'before' => nil, 'after' => \"moved by #{vector_mm.join(', ')} mm\" }\n            steps << ->(_created) { entity.transform!(Geom::Transformation.translation(local)) }\n          end\n        when 'skp.set_hidden'\n          hidden = op['hidden'] == true\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            changes << { 'op' => kind, 'target' => label(entity), 'field' => 'hidden', 'before' => entity.hidden?, 'after' => hidden }\n            steps << ->(_created) { entity.hidden = hidden }\n          end\n        when 'skp.erase'\n          # Erasing is the edit that loses the most; any committed change since the preview makes it stale.\n          fingerprints['revision'] = revision(model_id(model)).to_s\n          ids_param(op).each do |raw_id|\n            entity = target.call(raw_id)\n            # SketchUp deletes every face an erased edge bounds; the dialog line says so too.\n            edge = entity.is_a?(Sketchup::Edge)\n            warnings << 'Erasing an edge also deletes the faces it bounds.' if edge\n            changes << {\n              'op' => kind, 'target' => label(entity), 'field' => 'entity', 'before' => 'present',\n              'after' => edge ? 'erased, with the faces it bounds' : 'erased'\n            }\n            steps << ->(_created) { entity.erase! if entity.valid? }\n          end\n        when 'skp.add_box'\n          origin = vector_param(op['originMm'], 'originMm')\n          size = vector_param(op['sizeMm'], 'sizeMm')\n          fail!('INVALID_REQUEST', 'sizeMm values must all be greater than 0.') unless size.all? { |v| v > 0 }\n          tag = op['tag'] && name_param(op['tag'], kind)\n          fail!('TAG_NOT_FOUND', \"No tag named \\\"#{tag}\\\".\") if tag && !(find_tag(model, tag) || new_tags[tag])\n          material = op['material'] && name_param(op['material'], kind)\n          fail!('MATERIAL_NOT_FOUND', \"No material named \\\"#{material}\\\".\") if material && !(find_material(model, material) || new_materials[material])\n          box_name = op['name'].to_s.strip\n          changes << {\n            'op' => kind, 'target' => box_name.empty? ? 'new box' : \"new box \\\"#{box_name}\\\"\", 'field' => 'geometry',\n            'before' => nil, 'after' => \"#{size.join(' x ')} mm at #{origin.join(', ')} mm\"\n          }\n          steps << lambda do |created|\n            x, y, z = origin.map { |v| v / MM_PER_INCH }\n            w, d, h = size.map { |v| v / MM_PER_INCH }\n            group = model.entities.add_group\n            face = group.entities.add_face([x, y, z], [x + w, y, z], [x + w, y + d, z], [x, y + d, z])\n            face.reverse! if face.normal.z < 0\n            face.pushpull(h)\n            group.name = box_name unless box_name.empty?\n            group.layer = find_tag(model, tag) if tag\n            group.material = find_material(model, material) if material\n            created << { 'id' => group.persistent_id.to_s, 'type' => 'group', 'name' => box_name }\n          end\n        else\n          fail!('UNSUPPORTED_OPERATION', \"SketchUp does not support #{kind.inspect}.\")\n        end\n      end\n      { changes: changes, fingerprints: fingerprints, steps: steps, warnings: warnings.uniq }\n    end\n\n    def self.preview(params)\n      model = model_for(params['documentId'])\n      id = model_id(model)\n      planned = plan(model, params['operations'])\n      {\n        'documentId' => id,\n        'documentName' => model.title.to_s.empty? ? 'Untitled model' : model.title.to_s,\n        'revision' => revision(id),\n        'changes' => planned[:changes],\n        'fingerprints' => planned[:fingerprints],\n        'warnings' => planned[:warnings]\n      }\n    end\n\n    def self.stale_keys(expected, actual)\n      expected = expected.is_a?(Hash) ? expected : {}\n      (expected.keys | actual.keys).reject { |key| expected[key] == actual[key] }\n    end\n\n    def self.approved?(message)\n      UI.messagebox(message.to_s, MB_YESNO) == IDYES\n    end\n\n    # Inertia stops reading at deadlineAt and hangs up when it gives up, so a request past either must\n    # not change the model: nobody would learn that it did.\n    def self.abandoned?(params)\n      deadline = params['deadlineAt']\n      return true if deadline.is_a?(Numeric) && Time.now.to_f * 1000 >= deadline\n      client_gone?\n    end\n\n    def self.client_gone?\n      return false if @current_client.nil?\n      peek = @current_client.recv_nonblock(1, Socket::MSG_PEEK, exception: false)\n      peek.nil? || peek == ''\n    rescue IOError, SystemCallError\n      true\n    end\n\n    def self.expired(id)\n      { 'documentId' => id, 'status' => 'expired', 'revision' => revision(id) }\n    end\n\n    def self.apply(params)\n      model = model_for(params['documentId'], true)\n      id = model_id(model)\n      return expired(id) if abandoned?(params)\n      stale = stale_keys(params['expectedFingerprints'], plan(model, params['operations'])[:fingerprints])\n      unless stale.empty?\n        fail!('TARGET_CHANGED', \"The model changed since the preview (#{stale.first(5).join(', ')}). Preview the change again.\")\n      end\n      return { 'documentId' => id, 'status' => 'rejected', 'revision' => revision(id) } unless approved?(params['approvalMessage'])\n      return expired(id) if abandoned?(params)\n      # The designer said Yes, so Inertia never retries from here: failures report as consumed.\n      begin\n        # The dialog was modal, but re-check: the designer may have switched tabs.\n        model = model_for(params['documentId'], true)\n        planned = plan(model, params['operations'])\n        stale = stale_keys(params['expectedFingerprints'], planned[:fingerprints])\n        fail!('TARGET_CHANGED', 'The model changed while the approval dialog was open. Preview again.') unless stale.empty?\n        started = model.start_operation(params['title'].to_s.empty? ? 'Inertia edit' : \"Inertia: #{params['title']}\", true)\n      rescue BridgeError => error\n        raise if error.code == 'TARGET_CHANGED'\n        fail!('APPLY_FAILED', \"#{error.message} Nothing was changed.\")\n      rescue StandardError => error\n        fail!('APPLY_FAILED', \"SketchUp could not start the edit, so nothing was changed: #{error.message}\")\n      end\n      fail!('APPLY_FAILED', 'SketchUp was busy with another operation, so nothing was changed.') unless started\n      created = []\n      begin\n        planned[:steps].each { |step| step.call(created) }\n      rescue StandardError => error\n        model.abort_operation\n        fail!('APPLY_FAILED', \"SketchUp refused the edit, so nothing was changed: #{error.message}\")\n      end\n      begin\n        model.commit_operation\n      rescue StandardError => error\n        fail!('APPLY_UNCONFIRMED', \"SketchUp may not have kept the edit (#{error.message}). Check the model and its undo history.\")\n      end\n      {\n        'documentId' => id,\n        'status' => 'applied',\n        'revision' => revision(id),\n        'changes' => planned[:changes],\n        'created' => created\n      }\n    end\n\n    def self.save_copy(params)\n      model = model_for(params['documentId'])\n      path = params['path'].to_s\n      fail!('INVALID_REQUEST', 'The copy must be a .skp file.') unless path =~ /\\.skp\\z/i\n      fail!('ALREADY_EXISTS', 'A file already exists at that path. Pick a new name; copies never overwrite.') if File.exist?(path)\n      fail!('INVALID_REQUEST', 'The destination folder does not exist.') unless File.directory?(File.dirname(path))\n      saved = model.save_copy(path)\n      fail!('SAVE_FAILED', 'SketchUp could not save the copy.') unless saved && File.exist?(path)\n      {\n        'documentId' => model_id(model),\n        'path' => path,\n        'bytes' => File.size(path),\n        'originalPath' => model.path.to_s.empty? ? nil : model.path\n      }\n    end\n\n    def self.hello(_params)\n      {\n        'app' => 'sketchup',\n        'appVersion' => Sketchup.version.to_s,\n        'bridgeVersion' => BRIDGE_VERSION,\n        'protocol' => PROTOCOL,\n        'platform' => Sketchup.respond_to?(:platform) ? Sketchup.platform.to_s : RUBY_PLATFORM\n      }\n    end\n\n    METHODS = {\n      'hello' => :hello,\n      'documents' => :documents,\n      'selection' => :selection,\n      'query' => :query,\n      'info' => :info,\n      'capture' => :capture,\n      'preview' => :preview,\n      'apply' => :apply,\n      'save_copy' => :save_copy\n    }.freeze\n\n    # --- Transport -------------------------------------------------------\n\n    def self.secure_compare(left, right)\n      return false unless left.bytesize == right.bytesize\n      left.bytes.zip(right.bytes).inject(0) { |acc, (a, b)| acc | (a ^ b) }.zero?\n    end\n\n    def self.handle_line(line, token = @token)\n      request = JSON.parse(line.dup.force_encoding(Encoding::UTF_8))\n      request = {} unless request.is_a?(Hash)\n      id = request['id']\n      unless token && secure_compare(request['token'].to_s, token)\n        return { 'v' => PROTOCOL, 'id' => id, 'ok' => false, 'error' => { 'code' => 'UNAUTHORIZED', 'message' => 'Bad bridge token.' } }\n      end\n      method = METHODS[request['method'].to_s]\n      fail!('UNSUPPORTED_OPERATION', \"Unknown bridge method #{request['method'].inspect}.\") unless method\n      params = request['params'].is_a?(Hash) ? request['params'] : {}\n      { 'v' => PROTOCOL, 'id' => id, 'ok' => true, 'result' => send(method, params) }\n    rescue BridgeError => error\n      { 'v' => PROTOCOL, 'id' => id, 'ok' => false, 'error' => { 'code' => error.code, 'message' => error.message } }\n    rescue JSON::ParserError\n      { 'v' => PROTOCOL, 'id' => nil, 'ok' => false, 'error' => { 'code' => 'INVALID_REQUEST', 'message' => 'The request was not JSON.' } }\n    rescue StandardError => error\n      { 'v' => PROTOCOL, 'id' => id, 'ok' => false, 'error' => { 'code' => 'HOST_ERROR', 'message' => \"#{error.class}: #{error.message}\"[0, 500] } }\n    end\n\n    def self.home_dir\n      profile = ENV['USERPROFILE'].to_s\n      Sketchup.platform.to_s.include?('win') && !profile.empty? ? profile : Dir.home\n    rescue StandardError\n      Dir.home\n    end\n\n    def self.discovery_path\n      File.join(home_dir, '.inertia-cad', 'hosts', \"sketchup-#{Process.pid}.json\")\n    end\n\n    def self.write_discovery\n      path = discovery_path\n      FileUtils.mkdir_p(File.dirname(path))\n      payload = {\n        'app' => 'sketchup', 'pid' => Process.pid, 'port' => @port, 'token' => @token,\n        'bridgeVersion' => BRIDGE_VERSION, 'protocol' => PROTOCOL, 'appVersion' => Sketchup.version.to_s\n      }\n      temp = \"#{path}.#{SecureRandom.hex(4)}.tmp\"\n      File.open(temp, 'w', 0o600) { |file| file.write(JSON.generate(payload)) }\n      File.rename(temp, path)\n    end\n\n    def self.remove_discovery\n      path = discovery_path\n      File.delete(path) if File.exist?(path)\n    rescue StandardError\n      nil\n    end\n\n    def self.monotonic\n      Process.clock_gettime(Process::CLOCK_MONOTONIC)\n    end\n\n    def self.start\n      return if @server\n      @token = SecureRandom.hex(32)\n      @server = TCPServer.new('127.0.0.1', 0)\n      @port = @server.addr[1]\n      @clients = {}\n      @busy = false\n      write_discovery\n      Sketchup.add_observer(AppObserver.new)\n      @timer = UI.start_timer(0.05, true) { tick }\n    rescue StandardError => error\n      puts \"[Inertia CAD Bridge] could not start: #{error.message}\"\n    end\n\n    def self.stop\n      UI.stop_timer(@timer) if @timer\n      @timer = nil\n      (@clients || {}).keys.each { |socket| close_client(socket) }\n      @server.close if @server\n      @server = nil\n      remove_discovery\n    end\n\n    # The approval dialog runs a nested event loop that can fire this timer\n    # again; @busy keeps requests strictly one at a time.\n    def self.tick\n      return if @busy || @server.nil?\n      @busy = true\n      begin\n        # Connections past the cap wait in the listen backlog until a slot frees.\n        while @clients.size < MAX_CLIENTS\n          socket = @server.accept_nonblock(exception: false)\n          break unless socket.is_a?(TCPSocket) || socket.is_a?(Socket) || socket.is_a?(BasicSocket)\n          @clients[socket] = { buffer: String.new, seen: monotonic }\n        end\n        @clients.keys.each { |socket| service(socket) }\n        # After servicing, so a request that arrived during a long dialog is still answered.\n        now = monotonic\n        @clients.select { |_, client| now - client[:seen] > IDLE_SECONDS }.each_key { |socket| close_client(socket) }\n      rescue StandardError => error\n        puts \"[Inertia CAD Bridge] #{error.class}: #{error.message}\"\n      ensure\n        @busy = false\n      end\n    end\n\n    def self.service(socket)\n      chunk = socket.read_nonblock(65_536, exception: false)\n      return if chunk == :wait_readable\n      return close_client(socket) if chunk.nil?\n      client = @clients[socket]\n      client[:seen] = monotonic\n      buffer = client[:buffer]\n      buffer << chunk\n      return close_client(socket) if buffer.bytesize > MAX_REQUEST_BYTES\n      while (newline = buffer.index(\"\\n\"))\n        line = buffer.slice!(0..newline)\n        @current_client = socket\n        begin\n          response = handle_line(line)\n        ensure\n          @current_client = nil\n        end\n        socket.write(\"#{encode_response(response)}\\n\")\n        client[:seen] = monotonic\n      end\n    rescue IOError, SystemCallError\n      close_client(socket)\n    end\n\n    # Always one line back, even for a result JSON cannot hold (invalid UTF-8, NaN). The request\n    # may already have run, so Inertia must treat this as an unknown outcome, not a failure.\n    def self.encode_response(response)\n      JSON.generate(response)\n    rescue StandardError => error\n      JSON.generate(\n        'v' => PROTOCOL, 'id' => response['id'].is_a?(String) ? response['id'] : nil, 'ok' => false,\n        'error' => { 'code' => 'HOST_UNREADABLE', 'message' => \"SketchUp could not encode its answer (#{error.class}).\" }\n      )\n    end\n\n    def self.close_client(socket)\n      @clients.delete(socket) if @clients\n      socket.close unless socket.closed?\n    rescue StandardError\n      nil\n    end\n\n    class RevisionObserver < Sketchup::ModelObserver\n      def initialize(document_id)\n        super()\n        @document_id = document_id\n      end\n\n      def onTransactionCommit(_model)\n        CadBridge.bump(@document_id)\n      end\n\n      def onTransactionUndo(_model)\n        CadBridge.bump(@document_id)\n      end\n\n      def onTransactionRedo(_model)\n        CadBridge.bump(@document_id)\n      end\n\n      def onActivePathChanged(_model)\n        CadBridge.bump(@document_id)\n      end\n    end\n\n    class AppObserver < Sketchup::AppObserver\n      def onQuit\n        CadBridge.stop\n      end\n    end\n  end\nend\n\nInertia::CadBridge.start unless ENV['INERTIA_CAD_BRIDGE_TEST'] == '1'\n";
export const AUTOCAD_BRIDGE_PS1 = "# Inertia CAD Bridge for AutoCAD (Windows, full AutoCAD).\n#\n# Inertia runs this script with Windows PowerShell 5.1 once per request: one\n# JSON request on stdin, one JSON response on stdout. It attaches to the running\n# AutoCAD over COM, so nothing has to be installed or trusted inside AutoCAD.\n# Reads never change the drawing. Edits are re-validated against the preview's\n# fingerprints, shown to the designer in a native Yes/No dialog, and grouped in\n# one Undo mark. There is deliberately no way to send AutoCAD commands, LISP or\n# scripts through this bridge.\n#Requires -Version 5.1\n$ErrorActionPreference = 'Stop'\n\n$BridgeVersion = '1.0.0'\n$Protocol = 1\n$DefaultLimit = 100\n$MaxLimit = 500\n$MaxScan = 5000\n$MaxOperations = 50\n$MaxTargets = 500\n$MaxPlanTargets = 2000\n# Objects of a block definition read into an erase fingerprint; each costs a few COM calls.\n$MaxBlockDigestObjects = 500\n$MaxCoordinate = 1e12\n$MaxVertices = 200\n$MaxLayers = 1000\n$MaxBlocks = 500\n$MaxStyles = 100\n$MaxLayouts = 100\n# The server kills the bridge at its deadline (60 s for reads), so work stops well before it.\n$DefaultWorkMs = 35000\n$DeadlineMarginMs = 15000\n$DialogMarginMs = 30000\n$StaleSetSeconds = 600\n$ApplyMutexName = 'Local\\InertiaCadApply'\n$ReadMethods = @('selection', 'query', 'capture', 'info')\n$Clock = [System.Diagnostics.Stopwatch]::StartNew()\n$StartedUtc = [DateTime]::UtcNow\n$DeadlineMs = $null\n$WorkUntilMs = $DefaultWorkMs\n$ParentPid = $null\n\n$InsUnits = @{\n  0 = 'unitless'; 1 = 'in'; 2 = 'ft'; 3 = 'mi'; 4 = 'mm'; 5 = 'cm'; 6 = 'm'; 7 = 'km'; 8 = 'microinch'; 9 = 'mil'; 10 = 'yd'; 11 = 'angstrom'; 12 = 'nm'\n  13 = 'micron'; 14 = 'dm'; 15 = 'dam'; 16 = 'hm'; 17 = 'Gm'; 18 = 'au'; 19 = 'ly'; 20 = 'pc'; 21 = 'us-ft'; 22 = 'us-in'; 23 = 'us-yd'; 24 = 'us-mi'\n}\n$ShortTypes = @{\n  AcDbLine = 'LINE'; AcDbPolyline = 'LWPOLYLINE'; AcDb2dPolyline = 'POLYLINE'; AcDb3dPolyline = 'POLYLINE'\n  AcDbCircle = 'CIRCLE'; AcDbArc = 'ARC'; AcDbEllipse = 'ELLIPSE'; AcDbSpline = 'SPLINE'; AcDbPoint = 'POINT'\n  AcDbText = 'TEXT'; AcDbMText = 'MTEXT'; AcDbBlockReference = 'INSERT'; AcDbMInsertBlock = 'INSERT'\n  AcDbHatch = 'HATCH'; AcDbLeader = 'LEADER'; AcDbMLeader = 'MULTILEADER'; AcDbRasterImage = 'IMAGE'\n  AcDbViewport = 'VIEWPORT'; AcDbAttributeDefinition = 'ATTDEF'; AcDbXline = 'XLINE'; AcDbRay = 'RAY'\n  AcDbTable = 'ACAD_TABLE'; AcDbWipeout = 'WIPEOUT'; AcDbSolid = 'SOLID'; AcDb3dSolid = '3DSOLID'\n  AcDbRegion = 'REGION'; AcDbFace = '3DFACE'\n}\n$TextAlignments = @('left', 'center', 'right', 'aligned', 'middle', 'fit', 'top-left', 'top-center', 'top-right', 'middle-left', 'middle-center', 'middle-right', 'bottom-left', 'bottom-center', 'bottom-right')\n$MTextAttachments = @($null, 'top-left', 'top-center', 'top-right', 'middle-left', 'middle-center', 'middle-right', 'bottom-left', 'bottom-center', 'bottom-right')\n\n# --- Errors -------------------------------------------------------------\n\nfunction Fail([string]$Code, [string]$Message) {\n  $exception = New-Object System.Exception $Message\n  $exception.Data['inertia'] = $Code\n  throw $exception\n}\n\nfunction Get-ErrorShape($ErrorRecord) {\n  $exception = $ErrorRecord.Exception\n  while ($null -ne $exception.InnerException -and $null -eq $exception.Data['inertia']) {\n    if ($exception -is [System.Runtime.InteropServices.COMException]) { break }\n    $exception = $exception.InnerException\n  }\n  if ($null -ne $exception.Data['inertia']) {\n    return [ordered]@{ code = [string]$exception.Data['inertia']; message = $exception.Message }\n  }\n  $hresult = $exception.HResult\n  switch ($hresult) {\n    -2147221021 { return [ordered]@{ code = 'HOST_OFFLINE'; message = 'AutoCAD is not running. Open AutoCAD and the drawing, then try again.' } }\n    -2147221005 { return [ordered]@{ code = 'NOT_INSTALLED'; message = 'Full AutoCAD for Windows is not installed. AutoCAD LT has no automation interface.' } }\n    -2147418111 { return [ordered]@{ code = 'HOST_BUSY'; message = 'AutoCAD is busy (a command or dialog is open). Finish it and try again.' } }\n    -2147417846 { return [ordered]@{ code = 'HOST_BUSY'; message = 'AutoCAD is busy (a command or dialog is open). Finish it and try again.' } }\n  }\n  $text = $exception.Message\n  if ($text.Length -gt 500) { $text = $text.Substring(0, 500) }\n  return [ordered]@{ code = 'HOST_ERROR'; message = $text }\n}\n\n# --- Windows interop ----------------------------------------------------\n\n$InteropSource = @'\nusing System;\nusing System.Drawing;\nusing System.Drawing.Imaging;\nusing System.Runtime.InteropServices;\n\nnamespace InertiaCad {\n  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid(\"00000016-0000-0000-C000-000000000046\")]\n  public interface IOleMessageFilter {\n    [PreserveSig] int HandleInComingCall(int callType, IntPtr caller, int tickCount, IntPtr interfaceInfo);\n    [PreserveSig] int RetryRejectedCall(IntPtr callee, int tickCount, int rejectType);\n    [PreserveSig] int MessagePending(IntPtr callee, int tickCount, int pendingType);\n  }\n\n  // AutoCAD rejects COM calls while it is busy; retry for a while instead of failing at once.\n  public class MessageFilter : IOleMessageFilter {\n    [DllImport(\"ole32.dll\")]\n    private static extern int CoRegisterMessageFilter(IOleMessageFilter filter, out IOleMessageFilter previous);\n    public static void Register() { IOleMessageFilter previous; CoRegisterMessageFilter(new MessageFilter(), out previous); }\n    public static void Revoke() { IOleMessageFilter previous; CoRegisterMessageFilter(null, out previous); }\n    int IOleMessageFilter.HandleInComingCall(int callType, IntPtr caller, int tickCount, IntPtr interfaceInfo) { return 0; }\n    int IOleMessageFilter.RetryRejectedCall(IntPtr callee, int tickCount, int rejectType) {\n      return (rejectType == 1 || rejectType == 2) && tickCount < 15000 ? 250 : -1;\n    }\n    int IOleMessageFilter.MessagePending(IntPtr callee, int tickCount, int pendingType) { return 2; }\n  }\n\n  public static class Window {\n    [StructLayout(LayoutKind.Sequential)]\n    public struct Rect { public int Left, Top, Right, Bottom; }\n    [DllImport(\"user32.dll\")] private static extern bool GetWindowRect(IntPtr handle, out Rect rect);\n    [DllImport(\"user32.dll\")] private static extern bool PrintWindow(IntPtr handle, IntPtr hdc, uint flags);\n    [DllImport(\"user32.dll\")] public static extern bool IsIconic(IntPtr handle);\n    [DllImport(\"user32.dll\")] public static extern bool SetProcessDPIAware();\n\n    public static Bitmap Capture(IntPtr handle) {\n      Rect rect;\n      if (!GetWindowRect(handle, out rect)) return null;\n      int width = rect.Right - rect.Left, height = rect.Bottom - rect.Top;\n      if (width <= 0 || height <= 0) return null;\n      Bitmap bitmap = new Bitmap(width, height, PixelFormat.Format32bppArgb);\n      using (Graphics graphics = Graphics.FromImage(bitmap)) {\n        IntPtr hdc = graphics.GetHdc();\n        bool printed = PrintWindow(handle, hdc, 2);\n        graphics.ReleaseHdc(hdc);\n        if (!printed) { bitmap.Dispose(); return null; }\n      }\n      return bitmap;\n    }\n  }\n}\n'@\n\nfunction Get-InteropPath([string]$Source) {\n  $base = $env:LOCALAPPDATA\n  if ([string]::IsNullOrEmpty($base)) { $base = [System.IO.Path]::GetTempPath() }\n  return Join-Path (Join-Path $base 'InertiaCad') (\"interop-$(Get-Hash $Source).dll\")\n}\n\nfunction Initialize-Interop {\n  if ($null -ne ('InertiaCad.MessageFilter' -as [type])) { return }\n  $dll = Get-InteropPath $InteropSource\n  $folder = Split-Path -Parent $dll\n  if (Test-Path -LiteralPath $dll) {\n    try { Add-Type -Path $dll; return } catch { Remove-Item -LiteralPath $dll -Force -ErrorAction SilentlyContinue }\n  }\n  New-Item -ItemType Directory -Force -Path $folder | Out-Null\n  try {\n    Add-Type -TypeDefinition $InteropSource -ReferencedAssemblies System.Drawing -OutputAssembly $dll -OutputType Library\n    Add-Type -Path $dll\n  } catch {\n    Add-Type -TypeDefinition $InteropSource -ReferencedAssemblies System.Drawing\n  }\n}\n\nfunction Connect-AutoCAD {\n  [InertiaCad.MessageFilter]::Register()\n  return [System.Runtime.InteropServices.Marshal]::GetActiveObject('AutoCAD.Application')\n}\n\n# Returns yes, no, or expired when the deadline nears or the Inertia server that asked is gone.\nfunction Request-Approval([string]$Message, $CloseAtMs, $Parent) {\n  Add-Type -AssemblyName System.Windows.Forms\n  # Inertia starts this process hidden, and Windows applies that to the first window\n  # a process shows. Spend it on a throwaway form so the dialog is visible.\n  $spent = New-Object System.Windows.Forms.Form\n  $spent.ShowInTaskbar = $false\n  $spent.Opacity = 0\n  $spent.Show()\n  $spent.Close()\n  $form = New-Object System.Windows.Forms.Form\n  $form.Text = 'Inertia - approve AutoCAD edit'\n  $form.TopMost = $true\n  $form.StartPosition = 'CenterScreen'\n  $form.FormBorderStyle = 'FixedDialog'\n  $form.MinimizeBox = $false\n  $form.MaximizeBox = $false\n  $form.AutoSize = $true\n  $form.AutoSizeMode = 'GrowAndShrink'\n  $form.Padding = New-Object System.Windows.Forms.Padding 12\n  $layout = New-Object System.Windows.Forms.FlowLayoutPanel\n  $layout.FlowDirection = 'TopDown'\n  $layout.AutoSize = $true\n  $label = New-Object System.Windows.Forms.Label\n  $label.Text = $Message\n  $label.AutoSize = $true\n  $label.MaximumSize = New-Object System.Drawing.Size 560, 0\n  $buttons = New-Object System.Windows.Forms.FlowLayoutPanel\n  $buttons.AutoSize = $true\n  $buttons.Anchor = 'Right'\n  $yes = New-Object System.Windows.Forms.Button\n  $yes.Text = 'Yes'\n  $yes.DialogResult = 'Yes'\n  $no = New-Object System.Windows.Forms.Button\n  $no.Text = 'No'\n  $no.DialogResult = 'No'\n  $buttons.Controls.AddRange(@($yes, $no))\n  $layout.Controls.AddRange(@($label, $buttons))\n  $form.Controls.Add($layout)\n  $form.AcceptButton = $no\n  $form.CancelButton = $no\n  $form.ActiveControl = $no\n  $state = @{ expired = $false }\n  $timer = New-Object System.Windows.Forms.Timer\n  $timer.Interval = 500\n  $timer.Add_Tick({\n      if (($null -ne $CloseAtMs -and $script:Clock.ElapsedMilliseconds -ge $CloseAtMs) -or ($null -ne $Parent -and $Parent.HasExited)) {\n        $state.expired = $true\n        $form.Close()\n      }\n    })\n  $form.Add_Shown({ $form.Activate(); $timer.Start() })\n  try {\n    $answer = $form.ShowDialog()\n  } finally {\n    $timer.Dispose()\n    $form.Dispose()\n  }\n  if ($state.expired) { return 'expired' }\n  if ($answer -eq [System.Windows.Forms.DialogResult]::Yes) { return 'yes' }\n  return 'no'\n}\n\nfunction Enter-ApplyLock {\n  $mutex = New-Object System.Threading.Mutex($false, $ApplyMutexName)\n  $owned = $false\n  try { $owned = $mutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $owned = $true }\n  if (-not $owned) {\n    $mutex.Dispose()\n    Fail 'HOST_BUSY' 'Another Inertia edit is waiting for approval or running in AutoCAD. Try again when it is done.'\n  }\n  return $mutex\n}\n\nfunction Exit-ApplyLock($Mutex) {\n  try { $Mutex.ReleaseMutex() } catch { }\n  $Mutex.Dispose()\n}\n\nfunction Test-ApplyRunning {\n  try {\n    $mutex = Enter-ApplyLock\n    Exit-ApplyLock $mutex\n    return $false\n  } catch { return $true }\n}\n\n# --- Time ---------------------------------------------------------------\n\nfunction ConvertTo-UtcTime($Value) {\n  if ($Value -is [DateTime]) { return $Value.ToUniversalTime() }\n  $text = [string]$Value\n  $number = 0.0\n  if ($text -match '^\\d+(\\.\\d+)?$' -and [double]::TryParse($text, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$number)) {\n    return [DateTimeOffset]::FromUnixTimeMilliseconds([long]$number).UtcDateTime\n  }\n  $parsed = [DateTimeOffset]::MinValue\n  if ([DateTimeOffset]::TryParse($text, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$parsed)) { return $parsed.UtcDateTime }\n  Fail 'INVALID_REQUEST' 'deadlineAt must be an ISO time or epoch milliseconds.'\n}\n\n# Deadlines count from when this process started; without one, reads keep the default budget and dialogs never expire.\nfunction Set-Deadline($Request, $Params, [System.Diagnostics.Stopwatch]$Clock, [DateTime]$StartedUtc) {\n  $script:Clock = $Clock\n  $script:DeadlineMs = $null\n  $at = $Request.deadlineAt\n  if ($null -eq $at) { $at = $Params.deadlineAt }\n  $ms = $Request.deadlineMs\n  if ($null -eq $ms) { $ms = $Params.deadlineMs }\n  if ($null -ne $at) { $script:DeadlineMs = ((ConvertTo-UtcTime $at) - $StartedUtc).TotalMilliseconds }\n  elseif ($null -ne $ms) { $script:DeadlineMs = [double]$ms }\n  $script:WorkUntilMs = $(if ($null -ne $script:DeadlineMs) { $script:DeadlineMs - $DeadlineMarginMs } else { $DefaultWorkMs })\n  $script:ParentPid = $Request.parentPid\n  if ($null -eq $script:ParentPid) { $script:ParentPid = $Params.parentPid }\n}\n\nfunction Test-OutOfTime { return $script:Clock.ElapsedMilliseconds -ge $script:WorkUntilMs }\n\n# --- Small helpers ------------------------------------------------------\n\nfunction Get-Rounded($Value, [int]$Digits = 4) {\n  if ($null -eq $Value) { return $null }\n  return [Math]::Round([double]$Value, $Digits)\n}\n\nfunction Get-Degrees($Radians) {\n  if ($null -eq $Radians) { return $null }\n  return Get-Rounded ([double]$Radians * 180 / [Math]::PI) 3\n}\n\nfunction Get-Point($Point) {\n  if ($null -eq $Point) { return $null }\n  return , @((Get-Rounded $Point[0]), (Get-Rounded $Point[1]), (Get-Rounded $Point[2]))\n}\n\nfunction Limit-Text($Text, [int]$Max = 500) {\n  if ($null -eq $Text) { return $null }\n  $value = [string]$Text\n  if ($value.Length -gt $Max) { return $value.Substring(0, $Max) + '...' }\n  return $value\n}\n\nfunction Get-Limit($Params) {\n  $limit = 0\n  if ($null -ne $Params.limit) { $limit = [int]$Params.limit }\n  if ($limit -le 0) { $limit = $DefaultLimit }\n  return [Math]::Min($limit, $MaxLimit)\n}\n\nfunction Get-ShortType([string]$ObjectName) {\n  if ($ShortTypes.ContainsKey($ObjectName)) { return $ShortTypes[$ObjectName] }\n  if ($ObjectName -like 'AcDb*Dimension*') { return 'DIMENSION' }\n  return $ObjectName\n}\n\nfunction Get-Hash([string]$Text) {\n  $sha = [System.Security.Cryptography.SHA256]::Create()\n  try {\n    $bytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Text))\n    return ([System.BitConverter]::ToString($bytes) -replace '-', '').Substring(0, 16).ToLowerInvariant()\n  } finally { $sha.Dispose() }\n}\n\nfunction Get-Coordinate($Value, [string]$Name) {\n  $items = @($Value)\n  if ($items.Count -lt 2 -or $items.Count -gt 3) { Fail 'INVALID_REQUEST' \"$Name must be [x, y] or [x, y, z] in drawing units.\" }\n  $result = New-Object 'double[]' 3\n  for ($i = 0; $i -lt $items.Count; $i++) {\n    $number = 0.0\n    if (-not [double]::TryParse([string]$items[$i], [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$number) -or\n      -not ([Math]::Abs($number) -le $MaxCoordinate)) {\n      Fail 'INVALID_REQUEST' \"$Name is out of range: each value must be a number within $MaxCoordinate drawing units of the origin.\"\n    }\n    $result[$i] = $number\n  }\n  return , $result\n}\n\n$MTextCodes = [regex]'\\\\(?:U\\+([0-9A-Fa-f]{4})|S([^;]*);|([\\\\{}])|[PN~]|[fFHCcATQWp][^;]*;|[LlOoKk])|[{}]'\n\nfunction Get-PlainText([string]$Text) {\n  return $MTextCodes.Replace($Text, {\n      param($Match)\n      if ($Match.Groups[1].Success) { return [string][char][Convert]::ToInt32($Match.Groups[1].Value, 16) }\n      if ($Match.Groups[2].Success) { return $Match.Groups[2].Value -replace '[\\^#]', '/' }\n      if ($Match.Groups[3].Success) { return $Match.Groups[3].Value }\n      if ($Match.Value -cmatch '^\\\\[PN~]$') { return ' ' }\n      return ''\n    })\n}\n\nfunction Get-Vertices($Coordinates, [int]$Stride, [int]$Keep) {\n  $vertices = New-Object System.Collections.ArrayList\n  for ($i = 0; $i + $Stride -le $Coordinates.Count -and $vertices.Count -lt $MaxVertices; $i += $Stride) {\n    [void]$vertices.Add(@(for ($j = 0; $j -lt $Keep; $j++) { Get-Rounded $Coordinates[$i + $j] }))\n  }\n  return , $vertices.ToArray()\n}\n\nfunction Get-Extent($Entity) {\n  $min = $null\n  $max = $null\n  try { $Entity.GetBoundingBox([ref]$min, [ref]$max) } catch { return $null }\n  if ($null -eq $min -or $null -eq $max) { return $null }\n  return @{ min = $min; max = $max }\n}\n\n# DBMOD 8 (window) and 16 (view) flip on every zoom or pan, which leaves the file on disk current.\nfunction Test-UnsavedChanges($Doc) {\n  try { return ([int]$Doc.GetVariable('DBMOD') -band -bnot 24) -ne 0 } catch { return -not [bool]$Doc.Saved }\n}\n\nfunction Get-UnitsName($Doc) {\n  try { return $InsUnits[[int]$Doc.GetVariable('INSUNITS')] } catch { return $null }\n}\n\n# --- Documents ----------------------------------------------------------\n\nfunction Get-DocumentId($Doc) {\n  $full = [string]$Doc.FullName\n  if ([string]::IsNullOrEmpty($full)) { return 'acad:' + [string]$Doc.Name }\n  return 'acad:' + $full\n}\n\nfunction Get-ActiveDocumentId($Acad) {\n  try { return Get-DocumentId $Acad.ActiveDocument } catch { return $null }\n}\n\nfunction Get-Documents($Acad, $Params) {\n  $active = Get-ActiveDocumentId $Acad\n  $list = New-Object System.Collections.ArrayList\n  foreach ($doc in $Acad.Documents) {\n    $id = Get-DocumentId $doc\n    $full = [string]$doc.FullName\n    [void]$list.Add([ordered]@{\n        documentId   = $id\n        app          = 'autocad'\n        name         = [string]$doc.Name\n        path         = $(if ([string]::IsNullOrEmpty($full)) { $null } else { $full })\n        modified     = Test-UnsavedChanges $doc\n        active       = ($id -eq $active)\n        readOnly     = [bool]$doc.ReadOnly\n        displayUnits = Get-UnitsName $doc\n        activeLayout = $(try { [string]$doc.ActiveLayout.Name } catch { $null })\n      })\n  }\n  return [ordered]@{ documents = $list.ToArray() }\n}\n\nfunction Resolve-Document($Acad, [string]$DocumentId, [switch]$RequireActive) {\n  foreach ($doc in $Acad.Documents) {\n    if ((Get-DocumentId $doc) -eq $DocumentId) {\n      if ($RequireActive -and $DocumentId -ne (Get-ActiveDocumentId $Acad)) {\n        Fail 'INACTIVE_DOCUMENT' 'Switch AutoCAD to this drawing''s tab, then try again.'\n      }\n      return $doc\n    }\n  }\n  Fail 'DOCUMENT_NOT_FOUND' 'That drawing is no longer open in AutoCAD. Call inertia_cad_status for current documents.'\n}\n\nfunction Get-LayoutMap($Doc) {\n  $map = @{}\n  foreach ($layout in $Doc.Layouts) {\n    $map[[string]$layout.Block.ObjectID] = [string]$layout.Name\n  }\n  return $map\n}\n\nfunction Get-ModifiedState($Doc) {\n  $state = @{ dbmod = $null; count = $null }\n  try { $state.dbmod = [int]$Doc.GetVariable('DBMOD') } catch { }\n  try { $state.count = [int]$Doc.ModelSpace.Count } catch { }\n  return $state\n}\n\n# Reads must never change the drawing; if one did, stop before anything can save it.\nfunction Invoke-Read($Acad, $Params, [string]$Command) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $applying = Test-ApplyRunning\n  $before = Get-ModifiedState $doc\n  $concurrent = $false\n  try {\n    $result = & $Command $Acad $Params\n  } finally {\n    $after = Get-ModifiedState $doc\n    if (($null -ne $before.dbmod -and -not ($before.dbmod -band 1) -and ($after.dbmod -band 1)) -or\n      ($null -ne $before.count -and $null -ne $after.count -and $after.count -lt $before.count)) {\n      $concurrent = $applying -or (Test-ApplyRunning)\n      if (-not $concurrent) {\n        Fail 'READ_MODIFIED_DRAWING' 'The drawing changed while Inertia was only reading it. Do not save it and do not undo anything yet: tell the designer, who may have been editing at the same time, and let them decide whether to undo.'\n      }\n    }\n  }\n  if ($concurrent) { $result.concurrentEdit = $true }\n  return $result\n}\n\n# --- Entities -----------------------------------------------------------\n\nfunction Get-BoxRow($Extent) {\n  if ($null -eq $Extent) { return $null }\n  return , @(@((Get-Rounded $Extent.min[0]), (Get-Rounded $Extent.min[1])), @((Get-Rounded $Extent.max[0]), (Get-Rounded $Extent.max[1])))\n}\n\n# One property per try, so a row keeps what it could read when one property fails.\nfunction Add-Field($Row, [string]$Field, [scriptblock]$Read) {\n  try {\n    $value = & $Read\n    if ($null -ne $value) { $Row[$Field] = $value }\n  } catch { $Row.partial = $true }\n}\n\n# Polyline and old-style POLYLINE coordinates are in the object's coordinate system.\nfunction Add-Plane($Row, $Entity) {\n  $Row.elevation = Get-Rounded $Entity.Elevation\n  $normal = Get-Point $Entity.Normal\n  if ($null -ne $normal -and ($normal[0] -ne 0 -or $normal[1] -ne 0 -or $normal[2] -ne 1)) { $Row.normal = $normal }\n}\n\nfunction Get-ChordLength($Coordinates, [bool]$Closed) {\n  $sum = 0.0\n  $count = [int]($Coordinates.Count / 2)\n  if ($count -lt 2) { return 0.0 }\n  $last = $(if ($Closed) { $count } else { $count - 1 })\n  for ($i = 0; $i -lt $last; $i++) {\n    $j = ($i + 1) % $count\n    $sum += [Math]::Sqrt([Math]::Pow($Coordinates[2 * $j] - $Coordinates[2 * $i], 2) + [Math]::Pow($Coordinates[2 * $j + 1] - $Coordinates[2 * $i + 1], 2))\n  }\n  return $sum\n}\n\nfunction Get-EntityRow($Entity, $LayoutMap, $Options = @{}, $Extent = $null) {\n  $objectName = [string]$Entity.ObjectName\n  $row = [ordered]@{ handle = [string]$Entity.Handle; type = (Get-ShortType $objectName); layer = [string]$Entity.Layer }\n  if ($Options.bbox) {\n    if ($null -eq $Extent) { $Extent = Get-Extent $Entity }\n    $row.bbox = Get-BoxRow $Extent\n  }\n  if ($Options.compact) { return $row }\n  try { $row.color = [int]$Entity.Color } catch { }\n  $owner = [string]$Entity.OwnerID\n  if ($LayoutMap.ContainsKey($owner)) { $row.layout = $LayoutMap[$owner] } else { $row.nested = $true }\n  try {\n    switch -Wildcard ($objectName) {\n      'AcDbLine' { $row.start = Get-Point $Entity.StartPoint; $row.end = Get-Point $Entity.EndPoint; $row.length = Get-Rounded $Entity.Length }\n      'AcDbPolyline' {\n        $row.closed = [bool]$Entity.Closed\n        $length = [double]$Entity.Length\n        $row.length = Get-Rounded $length\n        $coordinates = @($Entity.Coordinates)\n        $row.vertexCount = [int]($coordinates.Count / 2)\n        $row.vertices = Get-Vertices $coordinates 2 2\n        if ($row.vertexCount -gt $MaxVertices) { $row.verticesTruncated = $true }\n        Add-Plane $row $Entity\n        # Arc segments make the length exceed the sum of chords, so straight polylines skip GetBulge.\n        if ([Math]::Abs($length - (Get-ChordLength $coordinates $row.closed)) -gt 1e-9 * [Math]::Max(1.0, $length)) {\n          $bulges = @(for ($i = 0; $i -lt $row.vertices.Count; $i++) { Get-Rounded $Entity.GetBulge($i) 6 })\n          if (@($bulges | Where-Object { $_ -ne 0 }).Count -gt 0) { $row.bulges = $bulges }\n        }\n        if ($row.closed) { $row.area = Get-Rounded $Entity.Area }\n      }\n      'AcDb[23]dPolyline' {\n        $flat = $objectName -eq 'AcDb2dPolyline'\n        $row.closed = [bool]$Entity.Closed\n        $row.length = Get-Rounded $Entity.Length\n        # Both kinds give three values per vertex; AutoCAD ignores a 2D polyline's Z (its elevation applies).\n        $coordinates = @($Entity.Coordinates)\n        $row.vertexCount = [int]($coordinates.Count / 3)\n        $row.vertices = Get-Vertices $coordinates 3 $(if ($flat) { 2 } else { 3 })\n        if ($row.vertexCount -gt $MaxVertices) { $row.verticesTruncated = $true }\n        if ($flat) { Add-Plane $row $Entity }\n      }\n      'AcDbSpline' {\n        $row.fitPointCount = [int]$Entity.NumberOfFitPoints\n        $row.controlPointCount = [int]$Entity.NumberOfControlPoints\n        $row.controlPoints = Get-Vertices @($Entity.ControlPoints) 3 3\n        if ($row.controlPointCount -gt $MaxVertices) { $row.controlPointsTruncated = $true }\n      }\n      'AcDbEllipse' {\n        $row.center = Get-Point $Entity.Center; $row.majorAxis = Get-Point $Entity.MajorAxis; $row.ratio = Get-Rounded $Entity.RadiusRatio 6\n        $row.startParam = Get-Rounded $Entity.StartParameter 6; $row.endParam = Get-Rounded $Entity.EndParameter 6\n      }\n      'AcDbCircle' { $row.center = Get-Point $Entity.Center; $row.radius = Get-Rounded $Entity.Radius }\n      'AcDbArc' {\n        $row.center = Get-Point $Entity.Center; $row.radius = Get-Rounded $Entity.Radius\n        $row.startAngleDeg = Get-Rounded ([double]$Entity.StartAngle * 180 / [Math]::PI) 3\n        $row.endAngleDeg = Get-Rounded ([double]$Entity.EndAngle * 180 / [Math]::PI) 3\n      }\n      'AcDbText' {\n        $row.text = Limit-Text $Entity.TextString; $row.position = Get-Point $Entity.InsertionPoint; $row.height = Get-Rounded $Entity.Height\n        Add-Field $row 'style' { [string]$Entity.StyleName }\n        Add-Field $row 'widthFactor' { Get-Rounded $Entity.ScaleFactor }\n        Add-Field $row 'rotationDeg' { Get-Degrees $Entity.Rotation }\n        Add-Field $row 'alignment' { $TextAlignments[[int]$Entity.Alignment] }\n        # Only left-aligned text is anchored at its insertion point.\n        if ($row.alignment -and $row.alignment -ne 'left') { Add-Field $row 'alignmentPoint' { Get-Point $Entity.TextAlignmentPoint } }\n      }\n      'AcDbMText' {\n        $row.text = Limit-Text (Get-PlainText $Entity.TextString); $row.position = Get-Point $Entity.InsertionPoint; $row.height = Get-Rounded $Entity.Height\n        Add-Field $row 'style' { [string]$Entity.StyleName }\n        Add-Field $row 'width' { Get-Rounded $Entity.Width }\n        Add-Field $row 'attachment' { $MTextAttachments[[int]$Entity.AttachmentPoint] }\n      }\n      'AcDbBlockReference' {\n        $row.block = $(try { [string]$Entity.EffectiveName } catch { [string]$Entity.Name })\n        $row.position = Get-Point $Entity.InsertionPoint\n        $row.rotationDeg = Get-Rounded ([double]$Entity.Rotation * 180 / [Math]::PI) 3\n        $row.scale = @((Get-Rounded $Entity.XScaleFactor), (Get-Rounded $Entity.YScaleFactor), (Get-Rounded $Entity.ZScaleFactor))\n        if ([bool]$Entity.HasAttributes) {\n          $attributes = New-Object System.Collections.ArrayList\n          foreach ($attribute in @($Entity.GetAttributes())) {\n            if ($attributes.Count -ge 30) { break }\n            [void]$attributes.Add([ordered]@{ tag = [string]$attribute.TagString; value = Limit-Text $attribute.TextString 200 })\n          }\n          $row.attributes = $attributes.ToArray()\n        }\n      }\n      'AcDb*Dimension*' {\n        $row.measurement = Get-Rounded $Entity.Measurement\n        $override = [string]$Entity.TextOverride\n        if ($override) { $row.textOverride = Limit-Text $override 200 }\n        Add-Field $row 'textPosition' { Get-Point $Entity.TextPosition }\n        # AutoCAD's COM interface has no definition points for rotated, radial or diametric dimensions.\n        switch ($objectName) {\n          'AcDbRotatedDimension' { Add-Field $row 'rotationDeg' { Get-Degrees $Entity.Rotation } }\n          { @('AcDbAlignedDimension', 'AcDbArcDimension') -contains $_ } {\n            Add-Field $row 'extLine1Point' { Get-Point $Entity.ExtLine1Point }\n            Add-Field $row 'extLine2Point' { Get-Point $Entity.ExtLine2Point }\n          }\n          'AcDbArcDimension' { Add-Field $row 'center' { Get-Point $Entity.CenterPoint } }\n          'AcDb3PointAngularDimension' {\n            Add-Field $row 'center' { Get-Point $Entity.AngleVertex }\n            Add-Field $row 'extLine1Point' { Get-Point $Entity.ExtLine1EndPoint }\n            Add-Field $row 'extLine2Point' { Get-Point $Entity.ExtLine2EndPoint }\n          }\n          'AcDb2LineAngularDimension' {\n            Add-Field $row 'extLine1Start' { Get-Point $Entity.ExtLine1StartPoint }\n            Add-Field $row 'extLine1End' { Get-Point $Entity.ExtLine1EndPoint }\n            Add-Field $row 'extLine2Start' { Get-Point $Entity.ExtLine2StartPoint }\n            Add-Field $row 'extLine2End' { Get-Point $Entity.ExtLine2EndPoint }\n          }\n          'AcDbRadialDimensionLarge' {\n            Add-Field $row 'center' { Get-Point $Entity.Center }\n            Add-Field $row 'chordPoint' { Get-Point $Entity.ChordPoint }\n          }\n        }\n      }\n      'AcDbHatch' { $row.pattern = [string]$Entity.PatternName; $row.area = Get-Rounded $Entity.Area }\n    }\n  } catch { $row.partial = $true }\n  return $row\n}\n\nfunction Get-Fingerprint($Entity) {\n  $parts = New-Object System.Collections.ArrayList\n  foreach ($name in 'ObjectName', 'Handle', 'OwnerID', 'Layer', 'Color', 'StartPoint', 'EndPoint', 'Center', 'Radius', 'InsertionPoint', 'Rotation', 'XScaleFactor', 'YScaleFactor', 'ZScaleFactor', 'Normal', 'TextString', 'Coordinates', 'Closed') {\n    $value = $null\n    try { $value = $Entity.$name } catch { }\n    if ($null -eq $value) { [void]$parts.Add('') } elseif ($value -is [System.Array]) { [void]$parts.Add((@($value) | ForEach-Object { Get-Rounded $_ 6 }) -join ',') } else { [void]$parts.Add([string]$value) }\n  }\n  try {\n    if ([bool]$Entity.HasAttributes) {\n      foreach ($attribute in @($Entity.GetAttributes())) { [void]$parts.Add([string]$attribute.TagString + '=' + [string]$attribute.TextString) }\n    }\n  } catch { }\n  return Get-Hash ($parts -join '|')\n}\n\n# What erasing a block insert removes from view: its definition's own objects.\n# An edit to the definition after the preview makes an erase proposal stale.\n# Nested blocks count by their own insert properties, not their contents.\nfunction Get-BlockDefinitionDigest($Doc, $Entity) {\n  if ([string]$Entity.ObjectName -ne 'AcDbBlockReference') { return $null }\n  try {\n    $block = $Doc.Blocks.Item([string]$Entity.Name)\n    $count = [int]$block.Count\n    $parts = New-Object System.Collections.ArrayList\n    [void]$parts.Add([string]$count)\n    for ($i = 0; $i -lt [Math]::Min($count, $MaxBlockDigestObjects); $i++) { [void]$parts.Add((Get-Fingerprint $block.Item($i))) }\n    return Get-Hash ($parts -join ';')\n  } catch {\n    return 'unreadable'\n  }\n}\n\nfunction Get-Selection($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $limit = Get-Limit $Params\n  $layoutMap = Get-LayoutMap $doc\n  $set = $doc.PickfirstSelectionSet\n  $count = [int]$set.Count\n  $items = New-Object System.Collections.ArrayList\n  $outOfTime = $false\n  for ($i = 0; $i -lt [Math]::Min($count, $limit); $i++) {\n    if ($items.Count -gt 0 -and (Test-OutOfTime)) { $outOfTime = $true; break }\n    [void]$items.Add((Get-EntityRow $set.Item($i) $layoutMap))\n  }\n  $result = [ordered]@{\n    documentId = Get-DocumentId $doc\n    units      = Get-UnitsName $doc\n    total      = $count\n    truncated  = $count -gt $items.Count\n    items      = $items.ToArray()\n  }\n  if ($outOfTime) { $result.partial = $true; $result.timeBudgetHit = $true }\n  if ($count -eq 0) {\n    if ((Get-DocumentId $doc) -ne (Get-ActiveDocumentId $Acad)) {\n      $result.hint = 'This drawing is not the active tab in AutoCAD, and AutoCAD only reports the selection of the active drawing. Switch to its tab, select the objects, and ask again.'\n    } elseif ($(try { [int]$doc.GetVariable('PICKFIRST') } catch { 1 }) -eq 0) {\n      $result.hint = 'PICKFIRST is 0 in AutoCAD, so objects selected outside a command are not readable. Set PICKFIRST to 1, select the objects again, and ask again.'\n    }\n  }\n  return $result\n}\n\nfunction Get-SetStamp { return [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() }\n\nfunction Select-Entities($Doc, [string[]]$Types, [string]$Layer, [string]$Layout, $Region) {\n  $codes = New-Object 'System.Collections.Generic.List[int16]'\n  $values = New-Object 'System.Collections.Generic.List[object]'\n  if ($Types.Count -gt 0) { $codes.Add(0); $values.Add(($Types -join ',')) }\n  if ($Layer) { $codes.Add(8); $values.Add($Layer) }\n  if ($Layout -and $Layout -ne '*') { $codes.Add(410); $values.Add($Layout) }\n  $missing = [System.Type]::Missing\n  $mode = 5\n  $point1 = $missing\n  $point2 = $missing\n  if ($null -ne $Region) {\n    # Window and crossing pick from the view, so AutoCAD may skip off-screen objects or catch near ones; callers re-check bounding boxes.\n    $mode = $(if ($Region.window) { 0 } else { 1 })\n    $point1 = $Region.min\n    $point2 = $Region.max\n  }\n  $name = 'INERTIACAD{0}_{1}' -f (Get-SetStamp), [guid]::NewGuid().ToString('N').Substring(0, 6)\n  $set = $Doc.SelectionSets.Add($name)\n  try {\n    if ($codes.Count -gt 0) {\n      $set.Select($mode, $point1, $point2, [int16[]]$codes.ToArray(), [object[]]$values.ToArray())\n    } else {\n      $set.Select($mode, $point1, $point2, $missing, $missing)\n    }\n  } catch {\n    Remove-SelectionSet $set\n    throw\n  }\n  # The comma keeps PowerShell from unrolling the set into its entities; Delete() on those erases them.\n  return , $set\n}\n\nfunction Remove-SelectionSet($Set) {\n  # Delete() on anything but our own selection set erases drawing objects.\n  if ($null -eq $Set -or $Set -is [System.Array]) { return }\n  $name = $null\n  try { $name = [string]$Set.Name } catch { }\n  if ($name -like 'INERTIACAD*') { try { $Set.Delete() } catch { } }\n}\n\n# A bridge killed on timeout never reaches its finally block, so earlier runs can leave sets behind.\nfunction Remove-StaleSelectionSets($Doc) {\n  $cutoff = (Get-SetStamp) - $StaleSetSeconds\n  $stale = New-Object System.Collections.ArrayList\n  $sets = $Doc.SelectionSets\n  for ($i = 0; $i -lt [int]$sets.Count; $i++) {\n    $set = $sets.Item($i)\n    $name = [string]$set.Name\n    if ($name -like 'INERTIACAD*' -and -not ($name -match '^INERTIACAD(\\d+)_' -and [long]$Matches[1] -ge $cutoff)) { [void]$stale.Add($set) }\n  }\n  foreach ($set in $stale) { Remove-SelectionSet $set }\n}\n\nfunction Get-Region($Within, [string]$Name = 'within') {\n  if ($null -eq $Within) { return $null }\n  $a = Get-Coordinate $Within.min \"$Name.min\"\n  $b = Get-Coordinate $Within.max \"$Name.max\"\n  $mode = 'crossing'\n  if ($Within.mode) { $mode = [string]$Within.mode }\n  if (@('crossing', 'window') -notcontains $mode) { Fail 'INVALID_REQUEST' \"$Name.mode must be crossing or window.\" }\n  $min = New-Object 'double[]' 3\n  $max = New-Object 'double[]' 3\n  for ($i = 0; $i -lt 2; $i++) { $min[$i] = [Math]::Min($a[$i], $b[$i]); $max[$i] = [Math]::Max($a[$i], $b[$i]) }\n  return @{ min = $min; max = $max; window = ($mode -eq 'window') }\n}\n\nfunction Test-Region($Extent, $Region) {\n  if ($null -eq $Extent) { return $true }\n  for ($i = 0; $i -lt 2; $i++) {\n    if ($Region.window) {\n      if ($Extent.min[$i] -lt $Region.min[$i] -or $Extent.max[$i] -gt $Region.max[$i]) { return $false }\n    } elseif ($Extent.max[$i] -lt $Region.min[$i] -or $Extent.min[$i] -gt $Region.max[$i]) { return $false }\n  }\n  return $true\n}\n\nfunction Get-SearchText($Entity) {\n  $text = ''\n  try { $text = [string]$Entity.TextString } catch { }\n  if ($text -match '[\\\\{]') { $text += ' ' + (Get-PlainText $text) }\n  try { if ([bool]$Entity.HasAttributes) { foreach ($attribute in @($Entity.GetAttributes())) { $text += ' ' + [string]$attribute.TextString } } } catch { }\n  try { $text += ' ' + [string]$Entity.EffectiveName } catch { }\n  return $text.ToLowerInvariant()\n}\n\nfunction Find-Entities($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $limit = Get-Limit $Params\n  $offset = 0\n  if ($null -ne $Params.cursor) { $offset = [Math]::Max(0, [int]$Params.cursor) }\n  $types = @($Params.types | Where-Object { $_ } | ForEach-Object { ([string]$_).ToUpperInvariant() })\n  foreach ($type in $types) { if ($type -notmatch '^[A-Z0-9_*]+$') { Fail 'INVALID_REQUEST' \"Unknown entity type $type. Use DXF names such as LINE, LWPOLYLINE, INSERT, TEXT, MTEXT.\" } }\n  $layout = 'Model'\n  if ($Params.layout) { $layout = [string]$Params.layout }\n  $needle = $null\n  if ($Params.textContains) { $needle = ([string]$Params.textContains).ToLowerInvariant() }\n  if ($Params.fields -and @('compact', 'full') -notcontains [string]$Params.fields) { Fail 'INVALID_REQUEST' 'fields must be compact or full.' }\n  $options = @{ compact = ($Params.fields -eq 'compact'); bbox = ($Params.bbox -eq $true) }\n  $region = Get-Region $Params.within\n  $layoutMap = Get-LayoutMap $doc\n  Remove-StaleSelectionSets $doc\n  $set = Select-Entities $doc $types ([string]$Params.layer) $layout $region\n  try {\n    $count = [int]$set.Count\n    $items = New-Object System.Collections.ArrayList\n    $total = $count\n    $capped = $false\n    $outOfTime = $false\n    $filtered = $false\n    if ($null -eq $needle -and $null -eq $region) {\n      for ($i = $offset; $i -lt [Math]::Min($count, $offset + $limit); $i++) {\n        if ($items.Count -gt 0 -and (Test-OutOfTime)) { $outOfTime = $true; break }\n        [void]$items.Add((Get-EntityRow $set.Item($i) $layoutMap $options))\n      }\n    } else {\n      # A text or region filter runs here, so the cursor is a scan position, not a match count:\n      # each call resumes where the last stopped and scans at least one object, so paging always\n      # progresses and a scan longer than one call's budget still reaches every match.\n      $filtered = $true\n      $positions = New-Object System.Collections.ArrayList\n      $resume = $null\n      $scanned = 0\n      $i = $offset\n      while ($i -lt $count) {\n        if ($scanned -ge $MaxScan) { $capped = $true; $resume = $i; break }\n        if ($scanned -gt 0 -and (Test-OutOfTime)) { $outOfTime = $true; $resume = $i; break }\n        $entity = $set.Item($i)\n        $i++\n        $scanned++\n        if ($null -ne $needle -and -not (Get-SearchText $entity).Contains($needle)) { continue }\n        $extent = $null\n        if ($null -ne $region) {\n          $extent = Get-Extent $entity\n          if (-not (Test-Region $extent $region)) { continue }\n        }\n        # A full page stops at the next match, which starts the next page.\n        if ($items.Count -ge $limit) { $resume = $i - 1; break }\n        [void]$items.Add((Get-EntityRow $entity $layoutMap $options $extent))\n        [void]$positions.Add($i - 1)\n      }\n    }\n    $result = [ordered]@{\n      documentId = Get-DocumentId $doc\n      units      = Get-UnitsName $doc\n      layout     = $layout\n      items      = $items.ToArray()\n    }\n    if ($filtered) {\n      # Objects of the requested types and layer, before the text or region filter.\n      $result.candidates = $count\n      if ($null -ne $resume -and $resume -lt $count) { $result.nextCursor = [string]$resume }\n      # Each row's scan position, so a caller that returns fewer rows can resume after the last one.\n      $result.scanPositions = $positions.ToArray()\n      if ($outOfTime) { $result.partial = $true; $result.timeBudgetHit = $true }\n    } else {\n      $result.total = $total\n      if ($outOfTime) {\n        $result.partial = $true\n        $result.timeBudgetHit = $true\n        if ($items.Count -gt 0) { $result.nextCursor = [string]($offset + $items.Count) }\n      } elseif ($offset + $limit -lt $total) { $result.nextCursor = [string]($offset + $limit) }\n    }\n    if ($capped) { $result.scanCapped = $true }\n    return $result\n  } finally {\n    Remove-SelectionSet $set\n  }\n}\n\nfunction Get-CaptureRegion($Params) {\n  if ($Params.extents -eq $true -and $null -ne $Params.bbox) { Fail 'INVALID_REQUEST' 'Pass extents or bbox, not both.' }\n  if ($Params.extents -eq $true) { return @{ extents = $true } }\n  $region = Get-Region $Params.bbox 'bbox'\n  if ($null -ne $region -and ($region.min[0] -eq $region.max[0] -or $region.min[1] -eq $region.max[1])) { Fail 'INVALID_REQUEST' 'bbox needs a width and a height.' }\n  return $region\n}\n\nfunction Get-ViewState($Doc) {\n  return @{ center = @($Doc.GetVariable('VIEWCTR')); size = [double]$Doc.GetVariable('VIEWSIZE') }\n}\n\nfunction Test-SameView($A, $B) {\n  $tolerance = 1e-6 * $A.size\n  if ([Math]::Abs($A.size - $B.size) -gt $tolerance) { return $false }\n  for ($i = 0; $i -lt 2; $i++) { if ([Math]::Abs($A.center[$i] - $B.center[$i]) -gt $tolerance) { return $false } }\n  return $true\n}\n\n# ZoomExtents recomputes EXTMIN/EXTMAX, which marks the drawing's system variables as changed (DBMOD 4),\n# so zoom to the stored extents with a window and fall back to ZoomExtents only when they are unusable.\nfunction Get-ExtentsWindow($Doc) {\n  try {\n    $min = @($Doc.GetVariable('EXTMIN'))\n    $max = @($Doc.GetVariable('EXTMAX'))\n    $width = [double]$max[0] - [double]$min[0]\n    $height = [double]$max[1] - [double]$min[1]\n    if (-not ($width -gt 0 -and $height -gt 0)) { return $null }\n    $margin = 0.02 * [Math]::Max($width, $height)\n    return @{\n      min = [double[]]@(([double]$min[0] - $margin), ([double]$min[1] - $margin), 0.0)\n      max = [double[]]@(([double]$max[0] + $margin), ([double]$max[1] + $margin), 0.0)\n    }\n  } catch { return $null }\n}\n\nfunction Get-Capture($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId) -RequireActive\n  $region = Get-CaptureRegion $Params\n  [void][InertiaCad.Window]::SetProcessDPIAware()\n  $handle = [IntPtr][long]$Acad.HWND\n  if ([InertiaCad.Window]::IsIconic($handle)) { Fail 'CAPTURE_FAILED' 'AutoCAD is minimized. Restore its window and try again.' }\n  $saved = $null\n  $restored = $true\n  try {\n    if ($null -ne $region) {\n      $saved = Get-ViewState $doc\n      if ($region.extents) {\n        $window = Get-ExtentsWindow $doc\n        if ($null -eq $window) { $Acad.ZoomExtents() } else { $Acad.ZoomWindow($window.min, $window.max) }\n      } else { $Acad.ZoomWindow($region.min, $region.max) }\n      try { $Acad.Update() } catch { }\n    }\n    $bitmap = [InertiaCad.Window]::Capture($handle)\n  } finally {\n    # ZoomPrevious restores center, height, twist and direction from AutoCAD's own view history. It runs\n    # only when the view really moved, so a zoom that changed nothing never pops the designer's earlier view.\n    if ($null -ne $saved) {\n      try {\n        if (-not (Test-SameView $saved (Get-ViewState $doc))) { $Acad.ZoomPrevious() }\n        $restored = Test-SameView $saved (Get-ViewState $doc)\n      } catch { $restored = $false }\n    }\n  }\n  if ($null -eq $bitmap) { Fail 'CAPTURE_FAILED' 'Windows could not capture the AutoCAD window.' }\n  try {\n    $maxWidth = [Math]::Min(2048, [Math]::Max(64, [int]$Params.maxWidth))\n    $maxHeight = [Math]::Min(2048, [Math]::Max(64, [int]$Params.maxHeight))\n    $scale = [Math]::Min(1.0, [Math]::Min($maxWidth / $bitmap.Width, $maxHeight / $bitmap.Height))\n    $width = [Math]::Max(1, [int][Math]::Round($bitmap.Width * $scale))\n    $height = [Math]::Max(1, [int][Math]::Round($bitmap.Height * $scale))\n    $scaled = New-Object System.Drawing.Bitmap $bitmap, $width, $height\n    $stream = New-Object System.IO.MemoryStream\n    try {\n      $scaled.Save($stream, [System.Drawing.Imaging.ImageFormat]::Png)\n      $data = [Convert]::ToBase64String($stream.ToArray())\n    } finally { $scaled.Dispose(); $stream.Dispose() }\n  } finally { $bitmap.Dispose() }\n  $result = [ordered]@{\n    documentId = Get-DocumentId $doc\n    width      = $width\n    height     = $height\n    pngBase64  = $data\n    scene      = $(try { [string]$doc.ActiveLayout.Name } catch { $null })\n  }\n  if (-not $restored) { $result.viewRestored = $false }\n  return $result\n}\n\n# --- Edits --------------------------------------------------------------\n\nfunction Get-Targets($Op) {\n  $handles = @($Op.handles | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })\n  if ($handles.Count -eq 0 -and $Op.handle) { $handles = @([string]$Op.handle) }\n  if ($handles.Count -eq 0) { Fail 'INVALID_REQUEST' \"$($Op.op) needs at least one handle.\" }\n  if ($handles.Count -gt $MaxTargets) { Fail 'INVALID_REQUEST' \"$($Op.op) accepts at most $MaxTargets handles.\" }\n  return , $handles\n}\n\nfunction Test-LayerName([string]$Name) {\n  if ([string]::IsNullOrWhiteSpace($Name) -or $Name.Length -gt 255 -or $Name -match '[<>/\\\\\":;?*|,=`]') {\n    Fail 'INVALID_REQUEST' \"Layer name `\"$Name`\" is not valid in AutoCAD.\"\n  }\n}\n\nfunction Get-Layer($Doc, [string]$Name) {\n  try { return $Doc.Layers.Item($Name) } catch { return $null }\n}\n\nfunction Get-Label($Entity) {\n  return \"$(Get-ShortType ([string]$Entity.ObjectName)) $([string]$Entity.Handle)\"\n}\n\nfunction Assert-InTime {\n  if (Test-OutOfTime) { Fail 'TIME_BUDGET' 'Checking this change took too long for one request. Split it into smaller changes.' }\n}\n\nfunction Get-WritableEntity($Doc, [string]$Handle, $LayoutMap, $Plan) {\n  Assert-InTime\n  try { $entity = $Doc.HandleToObject($Handle) } catch { Fail 'TARGET_NOT_FOUND' \"No object with handle $Handle in this drawing. Read the selection again.\" }\n  $layerName = $null\n  try { $layerName = [string]$entity.Layer } catch { }\n  if ([string]::IsNullOrEmpty($layerName)) {\n    Fail 'NOT_DRAWING_OBJECT' \"Handle $Handle is a $(Get-ShortType ([string]$entity.ObjectName)), not a drawing object. Use handles from inertia_cad_query_objects or inertia_cad_get_selection.\"\n  }\n  if (-not $LayoutMap.ContainsKey([string]$entity.OwnerID)) {\n    Fail 'NESTED_TARGET' \"$(Get-Label $entity) is inside a block definition; editing it would change every insert of that block. Pick top-level objects.\"\n  }\n  $layer = Get-Layer $Doc $layerName\n  if ($null -ne $layer -and [bool]$layer.Lock) { Fail 'LOCKED' \"$(Get-Label $entity) is on locked layer $layerName. Unlock it in AutoCAD first.\" }\n  $Plan.fingerprints['entity:' + $Handle] = Get-Fingerprint $entity\n  return $entity\n}\n\nfunction Add-Change($Plan, [string]$Op, [string]$Target, [string]$Field, $Before, $After) {\n  [void]$Plan.changes.Add([ordered]@{ op = $Op; target = $Target; field = $Field; before = $Before; after = $After })\n}\n\nfunction New-Plan($Acad, $Doc, $Operations) {\n  $operations = @($Operations)\n  if ($operations.Count -eq 0) { Fail 'INVALID_REQUEST' 'Give at least one operation.' }\n  if ($operations.Count -gt $MaxOperations) { Fail 'INVALID_REQUEST' \"At most $MaxOperations operations per change.\" }\n  $targetCount = 0\n  foreach ($op in $operations) { $targetCount += @($op.handles | Where-Object { $null -ne $_ }).Count }\n  if ($targetCount -gt $MaxPlanTargets) { Fail 'INVALID_REQUEST' \"At most $MaxPlanTargets target handles per change. Split it into smaller changes.\" }\n  $plan = @{\n    changes      = New-Object System.Collections.ArrayList\n    fingerprints = [ordered]@{}\n    steps        = New-Object System.Collections.ArrayList\n    warnings     = New-Object System.Collections.ArrayList\n  }\n  $layoutMap = Get-LayoutMap $Doc\n  $newLayers = @{}\n  # Layers as earlier operations in this batch leave them, so a later one is never skipped as a no-op.\n  $projectedLayers = @{}\n  foreach ($op in $operations) {\n    Assert-InTime\n    $kind = [string]$op.op\n    switch ($kind) {\n      'acad.create_layer' {\n        $name = [string]$op.name\n        Test-LayerName $name\n        if ($null -ne (Get-Layer $Doc $name) -or $newLayers.ContainsKey($name.ToLowerInvariant())) { Fail 'ALREADY_EXISTS' \"Layer `\"$name`\" already exists.\" }\n        $color = $null\n        if ($null -ne $op.color) { $color = [int]$op.color; if ($color -lt 1 -or $color -gt 255) { Fail 'INVALID_REQUEST' 'Layer color must be an AutoCAD color index from 1 to 255.' } }\n        $newLayers[$name.ToLowerInvariant()] = $true\n        $plan.fingerprints['layer:' + $name] = 'absent'\n        Add-Change $plan $kind $name 'layer' $null 'created'\n        [void]$plan.steps.Add(@{ kind = $kind; name = $name; color = $color })\n      }\n      'acad.set_layer' {\n        $name = [string]$op.layer\n        if ($null -eq (Get-Layer $Doc $name) -and -not $newLayers.ContainsKey($name.ToLowerInvariant())) { Fail 'LAYER_NOT_FOUND' \"No layer named `\"$name`\". Create it first with acad.create_layer.\" }\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          $current = [string]$entity.Layer\n          if ($projectedLayers.ContainsKey($handle)) { $current = $projectedLayers[$handle] }\n          if ($current -ieq $name) { [void]$plan.warnings.Add(\"$(Get-Label $entity) is already on layer $name.\"); continue }\n          $projectedLayers[$handle] = $name\n          Add-Change $plan $kind (Get-Label $entity) 'layer' $current $name\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity; value = $name })\n        }\n      }\n      'acad.set_color' {\n        $color = [int]$op.color\n        if ($color -lt 0 -or $color -gt 256) { Fail 'INVALID_REQUEST' 'color must be an AutoCAD color index: 0 ByBlock, 1-255, 256 ByLayer.' }\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          Add-Change $plan $kind (Get-Label $entity) 'color' ([int]$entity.Color) $color\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity; value = $color })\n        }\n      }\n      'acad.set_text' {\n        $text = [string]$op.text\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          if (@('AcDbText', 'AcDbMText') -notcontains [string]$entity.ObjectName) { Fail 'UNSUPPORTED_TARGET' \"$(Get-Label $entity) is not TEXT or MTEXT.\" }\n          Add-Change $plan $kind (Get-Label $entity) 'text' (Limit-Text $entity.TextString 200) (Limit-Text $text 200)\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity; value = $text })\n        }\n      }\n      'acad.set_attribute' {\n        $tag = [string]$op.tag\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          if ([string]$entity.ObjectName -ne 'AcDbBlockReference' -or -not [bool]$entity.HasAttributes) { Fail 'UNSUPPORTED_TARGET' \"$(Get-Label $entity) is not a block insert with attributes.\" }\n          $found = @(@($entity.GetAttributes()) | Where-Object { [string]$_.TagString -ieq $tag })\n          if ($found.Count -eq 0) { Fail 'ATTRIBUTE_NOT_FOUND' \"$(Get-Label $entity) has no attribute $tag.\" }\n          if ($found.Count -gt 1) { Fail 'AMBIGUOUS_ATTRIBUTE' \"$(Get-Label $entity) has several attributes tagged $tag.\" }\n          Add-Change $plan $kind \"$(Get-Label $entity) [$tag]\" 'attribute' (Limit-Text $found[0].TextString 200) (Limit-Text $op.value 200)\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity; tag = $tag; value = [string]$op.value })\n        }\n      }\n      'acad.move' {\n        $vector = Get-Coordinate $op.vector 'vector'\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          Add-Change $plan $kind (Get-Label $entity) 'position' $null (\"moved by \" + (($vector | ForEach-Object { Get-Rounded $_ }) -join ', '))\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity; vector = $vector })\n        }\n      }\n      'acad.erase' {\n        foreach ($handle in (Get-Targets $op)) {\n          $entity = Get-WritableEntity $Doc $handle $layoutMap $plan\n          $definition = Get-BlockDefinitionDigest $Doc $entity\n          if ($null -ne $definition) { $plan.fingerprints['block:' + $handle] = $definition }\n          Add-Change $plan $kind (Get-Label $entity) 'entity' 'present' 'erased'\n          [void]$plan.steps.Add(@{ kind = $kind; entity = $entity })\n        }\n      }\n      { @('acad.add_line', 'acad.add_polyline', 'acad.add_circle', 'acad.add_text') -contains $_ } {\n        $layer = $null\n        if ($op.layer) {\n          $layer = [string]$op.layer\n          if ($null -eq (Get-Layer $Doc $layer) -and -not $newLayers.ContainsKey($layer.ToLowerInvariant())) { Fail 'LAYER_NOT_FOUND' \"No layer named `\"$layer`\".\" }\n        }\n        $step = @{ kind = $kind; layer = $layer }\n        switch ($kind) {\n          'acad.add_line' {\n            $step.start = Get-Coordinate $op.start 'start'; $step.end = Get-Coordinate $op.end 'end'\n            $summary = \"line from $(($step.start | ForEach-Object { Get-Rounded $_ }) -join ', ') to $(($step.end | ForEach-Object { Get-Rounded $_ }) -join ', ')\"\n          }\n          'acad.add_polyline' {\n            $points = @($op.points)\n            if ($points.Count -lt 2 -or $points.Count -gt 1000) { Fail 'INVALID_REQUEST' 'points needs 2 to 1000 [x, y] pairs.' }\n            $flat = New-Object 'double[]' ($points.Count * 2)\n            for ($i = 0; $i -lt $points.Count; $i++) { $point = Get-Coordinate $points[$i] \"points[$i]\"; $flat[2 * $i] = $point[0]; $flat[2 * $i + 1] = $point[1] }\n            $step.coordinates = $flat; $step.closed = ($op.closed -eq $true)\n            $summary = \"polyline with $($points.Count) vertices$(if ($step.closed) { ', closed' })\"\n          }\n          'acad.add_circle' {\n            $step.center = Get-Coordinate $op.center 'center'; $step.radius = [double]$op.radius\n            if (-not ($step.radius -gt 0 -and $step.radius -lt $MaxCoordinate)) { Fail 'INVALID_REQUEST' 'radius must be greater than 0.' }\n            $summary = \"circle r=$(Get-Rounded $step.radius) at $(($step.center | ForEach-Object { Get-Rounded $_ }) -join ', ')\"\n          }\n          'acad.add_text' {\n            $step.position = Get-Coordinate $op.position 'position'; $step.height = [double]$op.height; $step.text = [string]$op.text\n            if (-not ($step.height -gt 0 -and $step.height -lt $MaxCoordinate)) { Fail 'INVALID_REQUEST' 'height must be greater than 0.' }\n            if ([string]::IsNullOrEmpty($step.text)) { Fail 'INVALID_REQUEST' 'text must not be empty.' }\n            $step.rotation = 0.0\n            if ($null -ne $op.rotationDeg) { $step.rotation = [double]$op.rotationDeg * [Math]::PI / 180 }\n            $summary = \"text `\"$(Limit-Text $step.text 60)`\"\"\n          }\n        }\n        $where = 'model space'\n        if ($layer) { $where += \" on layer $layer\" }\n        Add-Change $plan $kind \"new $($kind.Substring(9))\" 'geometry' $null \"$summary, $where\"\n        [void]$plan.steps.Add($step)\n      }\n      default { Fail 'UNSUPPORTED_OPERATION' \"AutoCAD does not support `\"$kind`\".\" }\n    }\n  }\n  return $plan\n}\n\n# Records when a failed step could not remove what it created, so the apply reports it.\nfunction Undo-Creation($Object) {\n  try { $Object.Delete() } catch { $script:StepLeftChanges = $true }\n}\n\nfunction Invoke-Step($Doc, $Step, $Created) {\n  switch ($Step.kind) {\n    'acad.create_layer' {\n      $layer = $Doc.Layers.Add($Step.name)\n      try { if ($null -ne $Step.color) { $layer.Color = $Step.color } } catch { Undo-Creation $layer; throw }\n    }\n    'acad.set_layer' { $Step.entity.Layer = (Get-Layer $Doc $Step.value).Name }\n    'acad.set_color' { $Step.entity.Color = $Step.value }\n    'acad.set_text' { $Step.entity.TextString = $Step.value }\n    'acad.set_attribute' {\n      foreach ($attribute in @($Step.entity.GetAttributes())) { if ([string]$attribute.TagString -ieq $Step.tag) { $attribute.TextString = $Step.value } }\n    }\n    'acad.move' {\n      $origin = New-Object 'double[]' 3\n      $Step.entity.Move($origin, $Step.vector)\n    }\n    'acad.erase' { $Step.entity.Delete() }\n    default {\n      $space = $Doc.ModelSpace\n      switch ($Step.kind) {\n        'acad.add_line' { $entity = $space.AddLine($Step.start, $Step.end) }\n        'acad.add_polyline' { $entity = $space.AddLightWeightPolyline($Step.coordinates) }\n        'acad.add_circle' { $entity = $space.AddCircle($Step.center, $Step.radius) }\n        'acad.add_text' { $entity = $space.AddText($Step.text, $Step.position, $Step.height) }\n      }\n      # A step either completes or leaves nothing behind, so a failure in the first step changed nothing.\n      try {\n        if ($Step.kind -eq 'acad.add_polyline' -and $Step.closed) { $entity.Closed = $true }\n        if ($Step.kind -eq 'acad.add_text' -and $Step.rotation -ne 0) { $entity.Rotation = $Step.rotation }\n        if ($Step.layer) { $entity.Layer = (Get-Layer $Doc $Step.layer).Name }\n      } catch { Undo-Creation $entity; throw }\n      [void]$Created.Add([ordered]@{ handle = [string]$entity.Handle; type = (Get-ShortType ([string]$entity.ObjectName)) })\n    }\n  }\n}\n\nfunction Get-StaleKeys($Expected, $Actual) {\n  $expectedMap = @{}\n  if ($null -ne $Expected) { foreach ($property in $Expected.PSObject.Properties) { $expectedMap[$property.Name] = [string]$property.Value } }\n  $stale = New-Object System.Collections.ArrayList\n  foreach ($key in $Actual.Keys) { if ($expectedMap[$key] -ne [string]$Actual[$key]) { [void]$stale.Add($key) } }\n  foreach ($key in $expectedMap.Keys) { if (-not $Actual.Contains($key)) { [void]$stale.Add($key) } }\n  return , $stale.ToArray()\n}\n\nfunction Get-Preview($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $plan = New-Plan $Acad $doc $Params.operations\n  return [ordered]@{\n    documentId   = Get-DocumentId $doc\n    documentName = [string]$doc.Name\n    changes      = $plan.changes.ToArray()\n    fingerprints = $plan.fingerprints\n    warnings     = @($plan.warnings | Select-Object -Unique)\n  }\n}\n\nfunction Invoke-Apply($Acad, $Params) {\n  $documentId = [string]$Params.documentId\n  $doc = Resolve-Document $Acad $documentId -RequireActive\n  $lock = Enter-ApplyLock\n  try {\n    $stale = Get-StaleKeys $Params.expectedFingerprints (New-Plan $Acad $doc $Params.operations).fingerprints\n    if ($stale.Count -gt 0) { Fail 'TARGET_CHANGED' \"The drawing changed since the preview ($((@($stale) | Select-Object -First 5) -join ', ')). Preview the change again.\" }\n    if ([int]$doc.GetVariable('CMDACTIVE') -ne 0) { Fail 'HOST_BUSY' 'AutoCAD has a command or dialog open. Finish it and try again.' }\n    if (-not ([int]$doc.GetVariable('UNDOCTL') -band 1)) {\n      Fail 'UNDO_DISABLED' 'Undo is turned off in this drawing, so the edit could not be reverted. Turn it back on in AutoCAD (UNDO, then Control, All) and try again.'\n    }\n    $closeAtMs = $null\n    if ($null -ne $script:DeadlineMs) { $closeAtMs = $script:DeadlineMs - $DialogMarginMs }\n    $answer = 'expired'\n    if ($null -eq $closeAtMs -or $script:Clock.ElapsedMilliseconds -lt $closeAtMs) {\n      $parent = $null\n      if ($null -ne $script:ParentPid) { try { $parent = [System.Diagnostics.Process]::GetProcessById([int]$script:ParentPid) } catch { } }\n      if ($null -eq $script:ParentPid -or ($null -ne $parent -and -not $parent.HasExited)) {\n        $answer = Request-Approval ([string]$Params.approvalMessage) $closeAtMs $parent\n      }\n    }\n    if ($answer -ne 'yes') { return [ordered]@{ documentId = $documentId; status = $(if ($answer -eq 'no') { 'rejected' } else { 'expired' }) } }\n    return Invoke-ApprovedSteps $Acad $Params\n  } finally {\n    Exit-ApplyLock $lock\n  }\n}\n\n# RPC failures leave it unknown whether the call ran inside AutoCAD; AutoCAD's own refusals mean it did not.\nfunction Test-RpcFailure($ErrorRecord) {\n  for ($exception = $ErrorRecord.Exception; $null -ne $exception; $exception = $exception.InnerException) {\n    if ($exception -isnot [System.Runtime.InteropServices.COMException]) { continue }\n    $hr = [System.BitConverter]::ToUInt32([System.BitConverter]::GetBytes([int]$exception.HResult), 0)\n    $code = $hr -band 0xFFFF\n    return (($hr -shr 16) -eq 0x8001) -or (($hr -shr 16) -eq 0x8007 -and $code -ge 1700 -and $code -le 1999)\n  }\n  return $false\n}\n\n# After the Yes the edit may have reached AutoCAD, so no failure here may read as \"not sent\": the server would retry and duplicate it.\nfunction Invoke-ApprovedSteps($Acad, $Params) {\n  $documentId = [string]$Params.documentId\n  # Without a deadline the designer may take as long as they like; the read budget must not fail the edit they approved.\n  if ($null -eq $script:DeadlineMs) { $script:WorkUntilMs = [double]::PositiveInfinity }\n  $created = New-Object System.Collections.ArrayList\n  $done = 0\n  $total = 0\n  $started = $false\n  $script:StepLeftChanges = $false\n  try {\n    $doc = Resolve-Document $Acad $documentId -RequireActive\n    $plan = New-Plan $Acad $doc $Params.operations\n    $stale = Get-StaleKeys $Params.expectedFingerprints $plan.fingerprints\n    if ($stale.Count -gt 0) { Fail 'TARGET_CHANGED' 'The drawing changed while the approval dialog was open. Preview again.' }\n    $total = $plan.steps.Count\n    $doc.StartUndoMark()\n    $started = $true\n    foreach ($step in $plan.steps) { Invoke-Step $doc $step $created; $done++ }\n  } catch {\n    $shape = Get-ErrorShape $_\n    if ($done -gt 0 -or $script:StepLeftChanges) { Fail 'PARTIALLY_APPLIED' \"AutoCAD stopped after $done of $total steps: $($shape.message). One Undo in AutoCAD reverts the steps that ran.\" }\n    if (-not $started -and $shape.code -eq 'TARGET_CHANGED') { throw }\n    if ($started -and (Test-RpcFailure $_)) {\n      Fail 'APPLY_UNCONFIRMED' 'AutoCAD stopped answering during the edit, so it is unknown whether it ran. Check the drawing before trying again; if it ran, one Undo reverts it.'\n    }\n    Fail 'APPLY_FAILED' \"AutoCAD refused the edit, so nothing was changed: $($shape.message)\"\n  } finally {\n    if ($started) { try { $doc.EndUndoMark() } catch { } }\n  }\n  return [ordered]@{ documentId = $documentId; status = 'applied'; changes = $plan.changes.ToArray(); created = $created.ToArray() }\n}\n\nfunction Get-CopyPath([string]$Path) {\n  $valid = $Path -match '^[A-Za-z]:\\\\' -and $Path.IndexOf(':', 2) -lt 0\n  if ($valid) { try { $Path = [System.IO.Path]::GetFullPath($Path) } catch { $valid = $false } }\n  if (-not $valid -or $Path -notmatch '^[A-Za-z]:\\\\' -or $Path.IndexOf(':', 2) -ge 0) {\n    Fail 'INVALID_REQUEST' 'The copy path must be a full path on a local drive, such as C:\\Projects\\Plan copy.dwg.'\n  }\n  if ($Path -notmatch '\\.dwg$') { Fail 'INVALID_REQUEST' 'The copy must be a .dwg file.' }\n  return $Path\n}\n\nfunction Save-Copy($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $path = Get-CopyPath ([string]$Params.path)\n  if (Test-Path -LiteralPath $path) { Fail 'ALREADY_EXISTS' 'A file already exists at that path. Pick a new name; copies never overwrite.' }\n  if (-not (Test-Path -LiteralPath (Split-Path -Parent $path) -PathType Container)) { Fail 'INVALID_REQUEST' 'The destination folder does not exist.' }\n  $source = [string]$doc.FullName\n  if ([string]::IsNullOrEmpty($source) -or [int]$doc.GetVariable('DWGTITLED') -ne 1) {\n    Fail 'UNTITLED_DOCUMENT' 'This drawing has never been saved. Save it once in AutoCAD, then ask for the copy again.'\n  }\n  # Saving to another name would switch the designer's tab to the copy, so only the file on disk is copied.\n  if (Test-UnsavedChanges $doc) {\n    Fail 'UNSAVED_CHANGES' 'The applied edits are in the open drawing but not in its file yet. Ask the designer to save it (Ctrl+S) when happy, then save the copy.'\n  }\n  try { [System.IO.File]::Copy($source, $path, $false) } catch {\n    if ([System.IO.File]::Exists($path)) { Fail 'ALREADY_EXISTS' 'A file already exists at that path. Pick a new name; copies never overwrite.' }\n    throw\n  }\n  return [ordered]@{ documentId = Get-DocumentId $doc; path = $path; bytes = (Get-Item -LiteralPath $path).Length; originalPath = $source }\n}\n\nfunction Read-SysVar($Doc, [string]$Name) {\n  try { return $Doc.GetVariable($Name) } catch { return $null }\n}\n\n# EntityColor packs the color method in its high byte (0xC2 is RGB) and the RGB in the low three.\nfunction Get-TrueColorHex($Layer) {\n  try {\n    $color = $Layer.TrueColor\n    $packed = [int]$color.EntityColor\n    $method = ($packed -shr 24) -band 0xFF\n    if ($method -eq 0xC2) { return '#{0:x6}' -f ($packed -band 0xFFFFFF) }\n    if ($method -ge 0xC0 -and $method -le 0xC8) { return $null }\n    if ([int]$color.ColorMethod -ne 0xC2) { return $null }\n    return '#{0:x2}{1:x2}{2:x2}' -f [int]$color.Red, [int]$color.Green, [int]$color.Blue\n  } catch { return $null }\n}\n\nfunction Get-Lineweight($Value) {\n  switch ([int]$Value) {\n    -1 { return 'ByLayer' }\n    -2 { return 'ByBlock' }\n    -3 { return 'Default' }\n  }\n  return [int]$Value / 100\n}\n\n# COM has no layer transparency; AutoCAD keeps it in AcCmTransparency xdata, where 0x02000000 marks\n# an alpha in the low byte. A layer without that xdata is opaque.\nfunction Get-LayerTransparency($Layer) {\n  try {\n    $types = $null\n    $values = $null\n    $Layer.GetXData('AcCmTransparency', [ref]$types, [ref]$values)\n    if ($null -eq $types) { return 0 }\n    $types = @($types)\n    $values = @($values)\n    for ($i = 0; $i -lt $types.Count; $i++) {\n      if ([int]$types[$i] -ne 1071) { continue }\n      $raw = [int]$values[$i]\n      if ((($raw -shr 24) -band 0xFF) -ne 2) { return $null }\n      return [int][Math]::Round((255 - ($raw -band 0xFF)) * 100 / 255)\n    }\n    return 0\n  } catch { return $null }\n}\n\nfunction Get-TextStyleRow($Style, [string]$Name) {\n  $row = [ordered]@{ name = $Name; font = $null; height = $null; widthFactor = $null }\n  try {\n    $file = [string]$Style.fontFile\n    if ($file) { $row.font = $file }\n    # Only TrueType styles have a typeface; SHX styles are named by their font file.\n    if (-not $file -or $file -match '\\.(ttf|ttc|otf)$') {\n      $face = ''; $bold = $false; $italic = $false; $charset = 0; $pitch = 0\n      $Style.GetFont([ref]$face, [ref]$bold, [ref]$italic, [ref]$charset, [ref]$pitch)\n      if ($face) { $row.font = [string]$face }\n    }\n  } catch { $row.partial = $true }\n  Add-Field $row 'height' { Get-Rounded $Style.Height }\n  Add-Field $row 'widthFactor' { Get-Rounded $Style.Width }\n  return $row\n}\n\nfunction Get-LayoutRow($Layout) {\n  $row = [ordered]@{ name = [string]$Layout.Name; paper = $null; device = $null; plotStyleTable = $null }\n  Add-Field $row 'paper' { [string]$Layout.CanonicalMediaName | Where-Object { $_ } }\n  Add-Field $row 'device' { [string]$Layout.ConfigName | Where-Object { $_ } }\n  Add-Field $row 'plotStyleTable' { [string]$Layout.StyleSheet | Where-Object { $_ } }\n  return $row\n}\n\nfunction Get-Info($Acad, $Params) {\n  $doc = Resolve-Document $Acad ([string]$Params.documentId)\n  $style = $Params.style -eq $true\n  $extents = $null\n  try {\n    $min = @($doc.GetVariable('EXTMIN'))\n    $max = @($doc.GetVariable('EXTMAX'))\n    if ((0..2 | Where-Object { -not ($min[$_] -le $max[$_]) }).Count -eq 0) { $extents = [ordered]@{ min = Get-Point $min; max = Get-Point $max } }\n  } catch { }\n  $outOfTime = $false\n  $layers = New-Object System.Collections.ArrayList\n  foreach ($layer in $doc.Layers) {\n    if ($layers.Count -ge $MaxLayers) { break }\n    if (Test-OutOfTime) { $outOfTime = $true; break }\n    $row = [ordered]@{\n      name     = [string]$layer.Name\n      on       = [bool]$layer.LayerOn\n      frozen   = [bool]$layer.Freeze\n      locked   = [bool]$layer.Lock\n      color    = [int]$layer.Color\n      linetype = [string]$layer.Linetype\n    }\n    if ($style) {\n      $row.trueColor = Get-TrueColorHex $layer\n      $row.lineweight = $(try { Get-Lineweight $layer.Lineweight } catch { $null })\n      $row.transparency = Get-LayerTransparency $layer\n    }\n    [void]$layers.Add($row)\n  }\n  $blocks = New-Object System.Collections.ArrayList\n  $blocksTruncated = $false\n  foreach ($block in $doc.Blocks) {\n    $name = [string]$block.Name\n    if ($name.StartsWith('*') -or $name.Contains('|') -or [bool]$block.IsLayout -or [bool]$block.IsXRef) { continue }\n    if ($blocks.Count -ge $MaxBlocks) { $blocksTruncated = $true; break }\n    if (Test-OutOfTime) { $outOfTime = $true; $blocksTruncated = $true; break }\n    [void]$blocks.Add($name)\n  }\n  $result = [ordered]@{\n    documentId      = Get-DocumentId $doc\n    units           = [ordered]@{ insUnits = (Get-UnitsName $doc); lunits = $(try { [int]$doc.GetVariable('LUNITS') } catch { $null }) }\n    extents         = $extents\n    layers          = $layers.ToArray()\n    layersTruncated = [int]$doc.Layers.Count -gt $layers.Count\n    blocks          = $blocks.ToArray()\n    blocksTruncated = $blocksTruncated\n    layouts         = $(if (-not $style) { , @(foreach ($layout in $doc.Layouts) { [string]$layout.Name }) })\n    entityCount     = [int]$doc.ModelSpace.Count\n    ucsIsWorld      = $(try { [int]$doc.GetVariable('WORLDUCS') -eq 1 } catch { $null })\n    viewTwistDeg    = $(try { Get-Rounded ([double]$doc.GetVariable('VIEWTWIST') * 180 / [Math]::PI) 3 } catch { $null })\n  }\n  if ($style) {\n    $layouts = New-Object System.Collections.ArrayList\n    $result.layoutsTruncated = $false\n    foreach ($layout in $doc.Layouts) {\n      if ($layouts.Count -ge $MaxLayouts) { $result.layoutsTruncated = $true; break }\n      if (Test-OutOfTime) { $outOfTime = $true; $result.layoutsTruncated = $true; break }\n      [void]$layouts.Add((Get-LayoutRow $layout))\n    }\n    $result.layouts = $layouts.ToArray()\n    $textStyles = New-Object System.Collections.ArrayList\n    $result.textStyles = $null; $result.textStylesTruncated = $false\n    foreach ($textStyle in $doc.TextStyles) {\n      if ($textStyles.Count -ge $MaxStyles) { $result.textStylesTruncated = $true; break }\n      if (Test-OutOfTime) { $outOfTime = $true; $result.textStylesTruncated = $true; break }\n      $name = [string]$textStyle.Name\n      # Shape files for complex linetypes are unnamed text styles; xref styles carry a pipe.\n      if ($name -and -not $name.Contains('|')) { [void]$textStyles.Add((Get-TextStyleRow $textStyle $name)) }\n    }\n    $result.textStyles = $textStyles.ToArray()\n    $dimNames = New-Object System.Collections.ArrayList\n    $result.dimStyles = $null; $result.dimStylesTruncated = $false\n    foreach ($dimStyle in $doc.DimStyles) {\n      if ($dimNames.Count -ge $MaxStyles) { $result.dimStylesTruncated = $true; break }\n      if (Test-OutOfTime) { $outOfTime = $true; $result.dimStylesTruncated = $true; break }\n      $name = [string]$dimStyle.Name\n      if (-not $name.Contains('|')) { [void]$dimNames.Add($name) }\n    }\n    # DIMTXT and the rest report the active style with any unsaved overrides, as new dimensions get them.\n    $result.dimStyles = [ordered]@{\n      names  = $dimNames.ToArray()\n      active = [ordered]@{\n        name     = Read-SysVar $doc 'DIMSTYLE'\n        dimtxt   = Get-Rounded (Read-SysVar $doc 'DIMTXT') 6\n        dimasz   = Get-Rounded (Read-SysVar $doc 'DIMASZ') 6\n        dimscale = Get-Rounded (Read-SysVar $doc 'DIMSCALE') 6\n        dimdec   = $(try { [int]$doc.GetVariable('DIMDEC') } catch { $null })\n      }\n    }\n    $result.current = [ordered]@{\n      layer     = Read-SysVar $doc 'CLAYER'\n      textStyle = Read-SysVar $doc 'TEXTSTYLE'\n      dimStyle  = $result.dimStyles.active.name\n      ltscale   = Get-Rounded (Read-SysVar $doc 'LTSCALE') 6\n    }\n  }\n  if ($outOfTime) { $result.partial = $true; $result.timeBudgetHit = $true }\n  return $result\n}\n\nfunction Get-Hello($Acad, $Params) {\n  return [ordered]@{\n    app           = 'autocad'\n    appVersion    = [string]$Acad.Version\n    product       = [string]$Acad.Name\n    bridgeVersion = $BridgeVersion\n    protocol      = $Protocol\n    platform      = 'windows'\n  }\n}\n\n$Methods = @{\n  hello     = 'Get-Hello'\n  documents = 'Get-Documents'\n  selection = 'Get-Selection'\n  query     = 'Find-Entities'\n  capture   = 'Get-Capture'\n  preview   = 'Get-Preview'\n  apply     = 'Invoke-Apply'\n  save_copy = 'Save-Copy'\n  info      = 'Get-Info'\n}\n\n# --- Entry point --------------------------------------------------------\n\nfunction Invoke-Request([string]$Raw, [scriptblock]$Connect, [System.Diagnostics.Stopwatch]$Clock = [System.Diagnostics.Stopwatch]::StartNew(), [DateTime]$StartedUtc = [DateTime]::UtcNow) {\n  $response = [ordered]@{ v = $Protocol; id = $null; ok = $false }\n  try {\n    $request = $Raw | ConvertFrom-Json\n    $response.id = $request.id\n    $command = $Methods[[string]$request.method]\n    if ($null -eq $command) { Fail 'UNSUPPORTED_OPERATION' \"Unknown bridge method `\"$($request.method)`\".\" }\n    $params = $request.params\n    if ($null -eq $params) { $params = New-Object PSObject }\n    Set-Deadline $request $params $Clock $StartedUtc\n    $acad = & $Connect\n    if ($ReadMethods -contains [string]$request.method) { $response.result = Invoke-Read $acad $params $command } else { $response.result = & $command $acad $params }\n    $response.ok = $true\n  } catch {\n    $response.error = Get-ErrorShape $_\n  }\n  return ConvertTo-Json -InputObject $response -Depth 32 -Compress\n}\n\nfunction Main {\n  $stdin = [Console]::OpenStandardInput()\n  $buffer = New-Object System.IO.MemoryStream\n  $stdin.CopyTo($buffer)\n  # Callers that pipe from PowerShell prepend a byte-order mark; JSON parsing rejects it.\n  $raw = [System.Text.Encoding]::UTF8.GetString($buffer.ToArray()).TrimStart([char]0xFEFF)\n  try {\n    $json = Invoke-Request $raw { Initialize-Interop | Out-Null; Connect-AutoCAD } $Clock $StartedUtc\n  } finally {\n    if ($null -ne ('InertiaCad.MessageFilter' -as [type])) { [InertiaCad.MessageFilter]::Revoke() }\n  }\n  $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)\n  $output = [Console]::OpenStandardOutput()\n  $output.Write($bytes, 0, $bytes.Length)\n  $output.Flush()\n}\n\nif ($env:INERTIA_CAD_BRIDGE_TEST -ne '1') { Main }\n";
export const CAD_GUIDE_AUTOCAD = "# AutoCAD guide\n\nRead before reading, drawing or editing a designer's AutoCAD work. For anything they will present, also read `inertia_cad_guide({topic: \"presentation\"})`.\n\n## MUST NOT\n\n- Reach AutoCAD or the designer's drawings any way but the `inertia_cad_*` tools: no COM, `SendCommand`, LISP, scripts or accoreconsole runs of your own. Parse only DXFs that you or `inertia_cad_export` wrote.\n- Save, close or undo in their session, or build new work inside their drawing.\n- Draw on `Defpoints`, or on `0` outside block definitions.\n- Give objects their own colour, linetype or lineweight unless asked. Properties stay ByLayer.\n- Scale geometry to fit a sheet. Model space is 1:1; scale is applied at plot.\n\n## MUST\n\n- Look before reasoning and after every change: `inertia_cad_export` `png` for saved files, `inertia_cad_capture_view {bbox}` for edits just applied (they are unsaved, so exports don't show them).\n- Say so when what you read is older than the open drawing (`liveUnsaved`, or `modified: true` in `inertia_cad_status`).\n- On `READ_MODIFIED_DRAWING`, stop every call on that drawing and tell the designer.\n\n## Procedure\n\n1. `inertia_cad_status`. Fix what `hint` names.\n2. `inertia_cad_document_info` once per drawing; add `style: true` before drawing anything.\n3. Take one path:\n   - **Understand it.** `inertia_cad_export` `png` of an `area`; the image is about 1600 px wide, so a smaller `area` zooms. For all the geometry, `dxf`, then ezdxf. Keep `inertia_cad_query_objects` for filtered lookups.\n   - **A small change they asked for, in their drawing.** See \"Editing the open drawing\".\n   - **Anything else**: a new drawing or sheet, hatches, arcs, dimensions, styles, more than 50 operations. See \"Building a new drawing\".\n\n## Reading their drawing\n\n- **Units.** `insUnits` is often wrong: drawings marked mm are often drawn in metres. Measure something known: a door leaf (0.7–1.0 m), a storey (2.5–3.5 m), a dimension's `measurement`. That gives the real mm per unit: 1000, 10 or 1.\n- **Scale.** `mmPerUnit` = real mm per unit ÷ scale denominator: 1:50 is 20 in metres, 0.02 in mm. Anything sized on paper is paper mm ÷ `mmPerUnit` in drawing units: 2.5 mm text at 1:50 in metres is 0.125.\n- **Plot styles.** If `layouts[].plotStyleTable` is a `.ctb`, colour sets the printed lineweight: give new content the colour of their layer with the same role.\n- **Text.** Copy style and height from their own text (`inertia_cad_query_objects {types: [\"TEXT\", \"MTEXT\"]}`), and from `dimStyles.active` for dimensions.\n- **Xrefs** are not listed by `inertia_cad_document_info`, and relative ones are missing from exports (see `warnings`). If content looks missing, tell the designer.\n- **Exports of their drawing** (`dxf`, `pdf`) land beside it; pass a `destination` in your own folder, which the designer approves in Inertia.\n\n## Editing the open drawing\n\n- Pass `layer` on every `add_*`; otherwise objects land on the current layer. `add_text` takes `current.textStyle`.\n- Prefer existing layers. `acad.create_layer` sets only a colour index, so ask before adding one.\n- `NESTED_TARGET` and `LOCKED` are the designer's decisions: report them, and don't press for exploding or unlocking.\n- `HOST_BUSY`, `INACTIVE_DOCUMENT`, `HOST_OFFLINE` and `UNDO_DISABLED` mean nothing was sent: once the designer fixes the cause, apply the same `proposalId`. `TARGET_CHANGED` or `PROPOSAL_EXPIRED`: read and preview again.\n\n## Building a new drawing\n\n1. Write a DXF with ezdxf, in the unit their geometry is really drawn in. Keep it in a new delivery folder: each output lands beside its `source`.\n2. Use their layer, text style and dim style names exactly: the build replaces your definitions with theirs. Copy blocks you reuse from a `dxf` export. Make repeated items blocks and dimensions real dimension entities. Run `doc.audit()`.\n3. `inertia_cad_export {source: \"<your.dxf>\", format: \"dwg\", template: \"<their drawing>\"}`. Only your model space is carried over, so compose sheets there.\n4. Render the result as `png` and compare colours, lineweights and fonts with theirs. Say what doesn't match.\n\n## Limits\n\n- A tool or parameter named here is missing (`inertia_cad_export`, `style`, `within`, `fields`): your schemas are stale. Ask for a fresh session; never fall back to COM or scripts.\n- `inertia_cad_status` reports `headless: false`: `inertia_cad_export` is unavailable. Use `inertia_cad_query_objects` and `inertia_cad_capture_view {bbox}`, and say what you couldn't check.\n";
export const CAD_GUIDE_SKETCHUP = "# SketchUp guide\n\nRead before reading or editing a designer's open SketchUp model. `inertia_cad_export` and `style` are AutoCAD-only.\n\n## MUST NOT\n\n- Reach SketchUp or the designer's `.skp` files any way but the `inertia_cad_*` tools: no Ruby, plugins or scripts.\n- Save, close or undo in their session.\n- Erase without explicit consent for those exact objects. Erasing an edge deletes its faces. Prefer `skp.set_hidden` or a tag, which are reversible.\n- Tidy tags, names, nesting, hidden state or materials nobody asked about.\n- Tag faces or edges. Raw geometry stays Untagged; only groups and components carry tags.\n- Read while an apply is `pending`. The approval dialog blocks SketchUp, so reads time out; call `inertia_cad_apply_changes` again instead.\n\n## MUST\n\n- Look before reasoning and after every change with `inertia_cad_capture_view`. A box on a hidden tag won't show.\n- Reuse their tags, materials and naming; create one only when none fits.\n- Name and tag every box you add.\n- Speak to the designer in their `displayUnits`. The tools always use mm, in world axes.\n\n## Procedure\n\n1. `inertia_cad_status {app: \"sketchup\"}`. Fix what `hint` names.\n2. `inertia_cad_document_info` once. Its tags, scenes, materials and component definitions are the designer's system.\n3. `inertia_cad_get_selection`. A non-empty `editingInside` means a group is open for editing: before you edit, ask the designer to close it, because entering or leaving one makes erase previews stale.\n4. `inertia_cad_query_objects` for lookups (`fields: \"compact\"` on big models).\n5. If reading answers the request, stop there.\n6. To edit: preview, tell the designer what will change, apply, then capture to verify.\n\n## Editing the model\n\n- **Instances.** Editing a top-level instance touches only that instance, and `skp.rename` renames the instance, not its definition. Anything inside a definition used more than once (copied groups included) is refused with `SHARED_DEFINITION`: target the top-level object, or ask the designer to Make Unique.\n- **Materials.** On a group or component, `skp.set_material` colours only its Default-material faces. On a face, it paints the front only.\n- **Boxes.** `skp.add_box` always makes a top-level group, extruded up +Z from its minimum corner `originMm`. Keep every side at least 1 mm; SketchUp drops smaller faces.\n- **Moves and names** work only on groups and components.\n- `LOCKED` is the designer's decision: report it, and don't press for unlocking.\n- `INACTIVE_DOCUMENT` means nothing was sent: once the model is in front, apply the same `proposalId`. `TARGET_CHANGED` or `PROPOSAL_EXPIRED`: read and preview again.\n\n## Limits\n\n- **View.** No camera, scene or style control. A capture is the current view, never larger than the viewport. Ask the designer to click a scene tab, then capture; the returned `scene` is the last tab clicked, and the camera may have moved since.\n- **Scenes.** A scene that saves Hidden Objects can undo `skp.set_hidden` when clicked. Use tags for visibility that differs per scene, and ask the designer to update the scenes they want changed.\n- **Modelling beyond boxes.** No faces, arcs, components, text, dimensions, textures, Make Unique, explode or purge. Describe the steps for the designer.\n- **Sheets and PDFs** come from the designer's own SketchUp or LayOut export; for what a sheet should look like, read `inertia_cad_guide({topic: \"presentation\"})`.\n- **LayOut** reads the saved `.skp`, so edits reach its viewports only after the designer saves and updates the reference. A `inertia_cad_save_copy` file is a different file.\n- A parameter named here is missing (`fields`, `within`): your schemas are stale. Ask for a fresh session; never fall back to Ruby or scripts.\n";
export const CAD_GUIDE_PRESENTATION = "# Presentation guide\n\nRead before making any drawing or sheet a designer will present: it must pass as their own work. Build it as `inertia_cad_guide({topic: \"autocad\"})` describes.\n\n## MUST NOT\n\n- Add what their sheets of that type omit: dimension chains, level marks, numbered callouts, legends, notes, key plans, frames, north arrows, logos, colour. That content goes in the README, or on a separate sheet if they ask.\n- Leave the drawing small. Under half the sheet means the scale is wrong.\n- Lay out or render sheets outside CAD (matplotlib, SVG, image tools). Plot with `inertia_cad_export`, unless `inertia_cad_status` reports `headless: false`; then say so.\n- Deliver a sheet you haven't viewed beside one of theirs.\n\n## MUST\n\n- Treat their finished sheets as the spec. The defaults below apply only where those sheets are silent.\n- Keep one scale per drawing type, and the same lineweights, greys, text sizes and title position across a set.\n\n## Procedure\n\n1. **Study 2–3 of their finished sheets of the same drawing type.** Their PDFs are best; otherwise `inertia_cad_export {format: \"png\", layout: \"<their layout>\"}`, or an `area` of model space. A plot-style warning means the render's lineweights aren't theirs. Note:\n   - the paper, and how much of it the drawing fills;\n   - what the sheet contains (poché, fills, people, title text) and what it leaves out;\n   - the title block's position, line order, wording, language and scale notation (`1:75` or `E 1:75`);\n   - fonts, text heights in mm, greys and lineweights (their standards are in `inertia_cad_document_info {style: true}`).\n2. **Choose the scale.** Size on paper = real mm ÷ scale denominator. Take the largest standard scale (1:10, 20, 25, 50, 75, 100, 200) at which the drawing fits inside the margins with the title zone clear; prefer their scale for that drawing type when it fills the sheet as well. Still under half the sheet: pair drawings (existing beside proposed).\n   - Example: a 9.9 × 8.9 m facade on A2 (594 × 420 mm) is 198 × 178 mm at 1:50, a third of the sheet: wrong. At 1:25 it is 396 × 356 mm: right.\n3. **Compose the sheet in model space.** `mmPerUnit` = real mm per drawing unit ÷ scale denominator (40 for metres at 1:25). The sheet is a rectangle of paper mm ÷ `mmPerUnit` drawing units; don't draw it. Place the drawing and title inside it as theirs sit, with text heights of paper mm ÷ `mmPerUnit`.\n4. **Render and compare.** `inertia_cad_export {format: \"png\", area: <sheet rectangle>}`, beside one of theirs at the same width. Check crops too: 1600 px hides hairlines on a large sheet. Repeat until the self-check passes.\n5. **Plot**: `inertia_cad_export {format: \"pdf\", area: <sheet rectangle>, mmPerUnit, paper}`.\n\nSketchUp sheets come from the designer's own scene or LayOut export; advise from this guide.\n\n## Defaults where their sheets are silent\n\n- **Fill.** The drawing takes 60–75% of the sheet, with even margins of at least 15 mm.\n- **Lineweights**, by layer, in three visible steps: 0.50 mm for cut, outline and ground line; 0.25–0.35 mm for openings and edges beyond; 0.13 mm for glazing, joints and hatch.\n- **Tone.** Solid dark grey (near #404040) for cut walls and ground; light grey fills (near #D0D0D0) behind the lines. Use true-colour greys: `monochrome.ctb` plots indexed colours black.\n- **Shadows and people** only if their sheets have them: one shadow grey and direction, and the designer's own people blocks.\n- **Type.** Their text styles and fonts, never `Standard` or stock SHX, in at most three sizes.\n\n## Self-check\n\nWith your sheet beside theirs at the same width:\n\n- Same contents: nothing extra, nothing missing.\n- The drawing fills the sheet as theirs do, and the title sits where theirs sits.\n- Cut and outline read first; hairlines stay light.\n- Greys, fonts and text sizes match.\n- Mixed in with their sheets, yours doesn't stand out.\n\n## Deliver\n\nA new folder such as `<project>/Inertia <topic> <date>/` with the DWG, the PDF and a `README.md`: sources, scale and paper, assumptions with their tolerance, annotation kept off the sheet, and what the designer should verify.\n";
